"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { DndContext, DragEndEvent, PointerSensor, useSensor, useSensors, closestCenter } from "@dnd-kit/core";
import { SortableContext, useSortable, verticalListSortingStrategy, arrayMove } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Plus, Trash2 } from "lucide-react";
import { api } from "@/lib/api";
import type { ContentSlide } from "@/lib/types";

interface Props {
  contentItemId: string;
  slides: ContentSlide[];
  onChange: () => void | Promise<unknown>;
}

export function CarouselSlideEditor({ contentItemId, slides, onChange }: Props) {
  const [order, setOrder] = useState<ContentSlide[]>(slides);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 6 } }));

  useEffect(() => { setOrder(slides); }, [slides]);

  const onDragEnd = async (e: DragEndEvent) => {
    const { active, over } = e;
    if (!over || active.id === over.id) return;
    const oldIdx = order.findIndex((s) => s.id === active.id);
    const newIdx = order.findIndex((s) => s.id === over.id);
    if (oldIdx === -1 || newIdx === -1) return;
    const next = arrayMove(order, oldIdx, newIdx);
    setOrder(next);
    await api.reorderContentSlides(next.map((s) => s.id));
    onChange();
  };

  const updateSlide = async (slideId: string, patch: Partial<Pick<ContentSlide, "title" | "body" | "notes">>) => {
    setOrder((prev) => prev.map((s) => s.id === slideId ? { ...s, ...patch } : s));
    await api.updateContentSlide(slideId, patch);
  };

  const addSlide = async () => {
    await api.createContentSlide(contentItemId);
    onChange();
  };

  const removeSlide = async (slideId: string) => {
    await api.deleteContentSlide(slideId);
    setConfirmDeleteId(null);
    onChange();
  };

  return (
    <section aria-label="Slides do carrossel" style={{ marginTop: 24 }}>
      <header style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
        <h3 style={{ fontFamily: "var(--font-poppins), Poppins, sans-serif", fontSize: 16, fontWeight: 600, color: "var(--text)", margin: 0 }}>
          Slides ({order.length})
        </h3>
        <button onClick={addSlide}
          style={{
            display: "inline-flex", alignItems: "center", gap: 6,
            padding: "7px 14px", borderRadius: 8,
            background: "var(--primary)", color: "#fff", border: "none",
            cursor: "pointer", fontSize: 12, fontWeight: 700, fontFamily: "inherit",
          }}>
          <Plus size={14} aria-hidden /> Adicionar slide
        </button>
      </header>

      {order.length === 0 ? (
        <div style={{ padding: "20px 0", textAlign: "center", fontSize: 13, color: "var(--text-muted)" }}>
          Sem slides. Clique em <strong>Adicionar slide</strong>.
        </div>
      ) : (
        <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={onDragEnd}>
          <SortableContext items={order.map((s) => s.id)} strategy={verticalListSortingStrategy}>
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {order.map((slide, idx) => (
                <SortableSlide
                  key={slide.id}
                  slide={slide}
                  index={idx}
                  onUpdate={(patch) => updateSlide(slide.id, patch)}
                  onRemove={() => setConfirmDeleteId(slide.id)}
                />
              ))}
            </div>
          </SortableContext>
        </DndContext>
      )}

      {confirmDeleteId && (
        <div role="dialog" aria-modal="true" style={overlay} onClick={() => setConfirmDeleteId(null)}>
          <div onClick={(e) => e.stopPropagation()} style={{
            background: "var(--surface)", border: "1px solid var(--card-border)",
            borderRadius: 12, padding: 20, width: "min(380px, 92vw)",
          }}>
            <h4 style={{ margin: "0 0 8px", fontSize: 14, fontWeight: 700 }}>Excluir slide?</h4>
            <p style={{ fontSize: 13, color: "var(--text-secondary)", marginBottom: 14 }}>
              O conteúdo do slide será perdido.
            </p>
            <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
              <button onClick={() => setConfirmDeleteId(null)} style={smallBtn}>Cancelar</button>
              <button onClick={() => removeSlide(confirmDeleteId)}
                style={{ ...smallBtn, background: "#E2445C", color: "#fff", border: "none" }}>
                Excluir
              </button>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

function SortableSlide({
  slide, index, onUpdate, onRemove,
}: {
  slide: ContentSlide;
  index: number;
  onUpdate: (patch: Partial<Pick<ContentSlide, "title" | "body" | "notes">>) => void;
  onRemove: () => void;
}) {
  // Campos controlados com auto-save. Antes eram `defaultValue` salvos só no
  // blur: trocar de ideia, arrastar o slide ou fechar a aba sem tirar o foco
  // jogava fora o que tinha sido escrito.
  const [campos, setCampos] = useState({ title: slide.title, body: slide.body, notes: slide.notes });
  const camposRef = useRef(campos);
  camposRef.current = campos;
  const sujoRef = useRef(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Só aceita a versão do servidor quando não há nada digitado pendente.
  useEffect(() => {
    if (sujoRef.current) return;
    setCampos({ title: slide.title, body: slide.body, notes: slide.notes });
  }, [slide.title, slide.body, slide.notes]);

  const salvar = useCallback(() => {
    if (timer.current) { clearTimeout(timer.current); timer.current = null; }
    if (!sujoRef.current) return;
    sujoRef.current = false;
    onUpdate({ ...camposRef.current });
  }, [onUpdate]);

  const salvarRef = useRef(salvar);
  salvarRef.current = salvar;

  const setCampo = (campo: "title" | "body" | "notes", valor: string) => {
    sujoRef.current = true;
    setCampos((prev) => ({ ...prev, [campo]: valor }));
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => salvarRef.current(), 800);
  };

  const salvarAgora = () => salvarRef.current();

  // Desmontar (trocar de ideia, excluir slide) não pode engolir o rascunho.
  useEffect(() => () => salvarRef.current(), []);

  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: slide.id });
  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.6 : 1,
  };
  return (
    <div ref={setNodeRef} style={{
      ...style,
      border: "1px solid var(--card-border)", borderRadius: 10,
      padding: 14, background: "var(--surface)",
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
        <span {...attributes} {...listeners}
          style={{ cursor: "grab", color: "var(--text-muted)", padding: "4px 8px", fontSize: 18 }}
          title="Arrastar pra reordenar">⠿</span>
        <span style={{ fontSize: 12, fontWeight: 700, color: "var(--primary)" }}>Slide {index + 1}</span>
        <button onClick={onRemove} aria-label="Excluir slide"
          style={{ marginLeft: "auto", background: "transparent", border: "none", color: "var(--text-muted)", cursor: "pointer", padding: 4, display: "flex" }}>
          <Trash2 size={14} />
        </button>
      </div>
      <input
        value={campos.title}
        onChange={(e) => setCampo("title", e.target.value)}
        onBlur={salvarAgora}
        placeholder="Título do slide..."
        style={{
          width: "100%", padding: "6px 0", marginBottom: 8,
          background: "transparent", border: "none", borderBottom: "1px solid transparent",
          color: "var(--text)", fontSize: 14, fontWeight: 600, outline: "none", fontFamily: "inherit",
        }}
        onFocus={(e) => (e.currentTarget.style.borderBottomColor = "var(--primary)")}
      />
      <textarea
        value={campos.body}
        onChange={(e) => setCampo("body", e.target.value)}
        onBlur={salvarAgora}
        placeholder="Conteúdo do slide..."
        rows={3}
        style={{
          width: "100%", padding: "8px 10px",
          background: "var(--input-bg)", border: "1px solid var(--input-border)",
          color: "var(--text)", fontSize: 13, lineHeight: 1.5,
          outline: "none", fontFamily: "inherit", resize: "vertical", borderRadius: 6,
        }}
      />
      <textarea
        value={campos.notes}
        onChange={(e) => setCampo("notes", e.target.value)}
        onBlur={salvarAgora}
        placeholder="Notas visuais (pra Ariel/designer)..."
        rows={2}
        style={{
          width: "100%", padding: "8px 10px", marginTop: 8,
          background: "color-mix(in srgb, var(--primary) 5%, transparent)",
          border: "1px dashed var(--card-border)",
          color: "var(--text)", fontSize: 12, lineHeight: 1.4,
          outline: "none", fontFamily: "inherit", resize: "vertical", borderRadius: 6,
        }}
      />
    </div>
  );
}

const overlay: React.CSSProperties = {
  position: "fixed", inset: 0, background: "var(--overlay)", backdropFilter: "blur(4px)",
  display: "flex", alignItems: "center", justifyContent: "center", zIndex: 2000,
};

const smallBtn: React.CSSProperties = {
  padding: "8px 14px", borderRadius: 8,
  border: "1px solid var(--border-strong)", background: "transparent",
  color: "var(--text)", fontSize: 12, fontWeight: 600, cursor: "pointer",
  fontFamily: "inherit",
};

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Archive, Copy, FolderInput, Plus, Search, Sparkles, Trash2,
} from "lucide-react";
import { api } from "@/lib/api";
import type { ContentFormat, ContentItem, ContentPlatform, ContentStatus, Project, User } from "@/lib/types";
import { useContentItem, useContentItems } from "@/lib/use-content";
import { UserAvatar } from "@/components/ui/user-avatar";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { ContentListItem } from "@/components/content/ContentListItem";
import { CarouselSlideEditor } from "@/components/content/CarouselSlideEditor";
import { CommentsThread } from "@/components/content/CommentsThread";
import { ALL_FORMATS, FormatIcon, formatLabel } from "@/components/content/FormatIcon";
import { ALL_STATUSES, STATUS_META, StatusBadge } from "@/components/content/StatusBadge";
import { ALL_PLATFORMS, PLATFORM_META } from "@/components/content/PlatformBadge";

interface Filters {
  status: ContentStatus[];
  format: ContentFormat[];
  platform: ContentPlatform | "all";
  assignedTo: string | "all" | "me" | "other";
  search: string;
}

const DEFAULT_FILTERS: Filters = {
  status: ["idea", "in_production"],
  format: [],
  platform: "all",
  assignedTo: "all",
  search: "",
};

const FILTERS_STORAGE_KEY_PREFIX = "clareza-content-filters:";

export interface ContentBoardProps {
  currentUser: User;
  users: User[];
  projects: Project[];
  /** Quando definido, escopa lista e novos itens a este workspace. */
  workspaceId?: string;
  workspaceName?: string;
  /** true = dentro do app (altura 100%, sem botão "voltar"). */
  embedded?: boolean;
  initialItemId?: string | null;
  onBackHome?: () => void;
}

export function ContentBoard({
  currentUser, users, projects, workspaceId, workspaceName, embedded, initialItemId, onBackHome,
}: ContentBoardProps) {
  const [selectedId, setSelectedId] = useState<string | null>(initialItemId ?? null);
  const [filters, setFilters] = useState<Filters>(DEFAULT_FILTERS);
  const searchRef = useRef<HTMLInputElement>(null);

  const storageKey = `${FILTERS_STORAGE_KEY_PREFIX}${currentUser.id}:${workspaceId ?? "all"}`;

  // Restaura filtros do localStorage (por usuário + workspace)
  useEffect(() => {
    const saved = localStorage.getItem(storageKey);
    if (saved) {
      try { setFilters(JSON.parse(saved)); } catch {}
    } else {
      setFilters(DEFAULT_FILTERS);
    }
  }, [storageKey]);

  useEffect(() => {
    localStorage.setItem(storageKey, JSON.stringify(filters));
  }, [filters, storageKey]);

  // Resolve assignedTo "me"/"other" pra ID concreto
  const resolvedAssignedTo = useMemo(() => {
    if (filters.assignedTo === "all") return undefined;
    if (filters.assignedTo === "me") return currentUser.id;
    if (filters.assignedTo === "other") {
      const other = users.find((u) => u.id !== currentUser.id && u.canAccessContent);
      return other?.id;
    }
    return filters.assignedTo;
  }, [filters.assignedTo, currentUser, users]);

  const listFilters = useMemo(() => ({
    status: filters.status,
    format: filters.format,
    platform: filters.platform === "all" ? undefined : filters.platform,
    assignedTo: resolvedAssignedTo,
    workspaceId,
    search: filters.search || undefined,
  }), [filters, resolvedAssignedTo, workspaceId]);

  const { items = [], mutate: mutateList, isLoading: listLoading } = useContentItems(listFilters);

  // Auto-seleciona o primeiro item só quando não há nada aberto. Antes o
  // editor pulava de ideia sozinho: bastava o título mudar e a ideia sair
  // do filtro pra lista revalidar e trocar o que estava sendo escrito.
  useEffect(() => {
    if (!selectedId && items.length > 0) setSelectedId(items[0].id);
  }, [items, selectedId]);

  const createNew = useCallback(async () => {
    const created = await api.createContentItem(workspaceId ? { workspaceId } : {});
    await mutateList();
    setSelectedId(created.id);
  }, [mutateList, workspaceId]);

  // Atalhos globais
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement | null;
      const typing = t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable);
      if (typing) return;
      if (e.key === "n" && !e.ctrlKey && !e.metaKey) { e.preventDefault(); createNew(); }
      if (e.key === "/") { e.preventDefault(); searchRef.current?.focus(); }
      if (e.key === "j" || e.key === "k") {
        if (items.length === 0) return;
        const idx = items.findIndex((i) => i.id === selectedId);
        const nextIdx = e.key === "j" ? Math.min(items.length - 1, idx + 1) : Math.max(0, idx - 1);
        setSelectedId(items[nextIdx]?.id ?? null);
        e.preventDefault();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, selectedId, createNew]);

  return (
    <div style={{ display: "flex", flexDirection: "column", height: embedded ? "100%" : "100vh", minHeight: 0, background: "var(--bg)" }}>
      <ContentTopBar
        filters={filters}
        onFiltersChange={setFilters}
        onNewIdea={createNew}
        currentUser={currentUser}
        users={users}
        searchRef={searchRef}
        onBackHome={!embedded ? onBackHome : undefined}
        workspaceName={workspaceName}
      />

      <div className="content-shell" style={{ flex: 1, display: "grid", gridTemplateColumns: "320px 1fr 300px", minHeight: 0 }}>
        {/* Lista */}
        <aside style={{
          padding: "16px 12px",
          background: "color-mix(in srgb, var(--primary) 2%, var(--surface))",
          borderRight: "1px solid var(--card-border)",
          overflowY: "auto",
        }}>
          {listLoading && items.length === 0 ? (
            <div style={{ padding: 16, fontSize: 13, color: "var(--text-muted)", textAlign: "center" }}>Carregando…</div>
          ) : items.length === 0 ? (
            <EmptyList onNew={createNew} />
          ) : (
            <AnimatePresence initial={false}>
              {items.map((item) => (
                <ContentListItem
                  key={item.id}
                  item={item}
                  active={item.id === selectedId}
                  onClick={() => setSelectedId(item.id)}
                  users={users}
                />
              ))}
            </AnimatePresence>
          )}
        </aside>

        {/* Editor */}
        <section style={{ overflowY: "auto", padding: "32px", background: "var(--surface)" }}>
          {selectedId ? (
            <ContentEditor
              key={selectedId}
              contentId={selectedId}
              currentUser={currentUser}
              users={users}
              projects={projects}
              onMutateList={mutateList}
              onSelect={setSelectedId}
            />
          ) : (
            <div style={{ display: "grid", placeItems: "center", height: "100%", color: "var(--text-muted)" }}>
              Selecione uma ideia ou crie uma nova.
            </div>
          )}
        </section>

        {/* Meta + comments */}
        <aside style={{
          padding: 20,
          background: "color-mix(in srgb, var(--primary) 2%, var(--surface))",
          borderLeft: "1px solid var(--card-border)",
          overflowY: "auto",
        }}>
          {selectedId && (
            <MetaAndComments
              contentId={selectedId}
              currentUser={currentUser}
              users={users}
              projects={projects}
            />
          )}
        </aside>
      </div>

      <style>{`
        .spin { animation: spin 1s linear infinite; }
        @keyframes spin { to { transform: rotate(360deg); } }
        @media (max-width: 1279px) {
          .content-shell { grid-template-columns: 320px 1fr !important; }
          .content-shell > aside:last-of-type { display: none; }
        }
        @media (max-width: 1023px) {
          .content-shell { grid-template-columns: 1fr !important; }
          .content-shell > aside:first-of-type {
            display: ${selectedId ? "none" : "block"};
          }
          .content-shell > section {
            display: ${selectedId ? "block" : "none"};
          }
        }
      `}</style>
    </div>
  );
}

// ─── TOP BAR ───────────────────────────────────────────────────────────

function ContentTopBar({
  filters, onFiltersChange, onNewIdea, currentUser, users, searchRef, onBackHome, workspaceName,
}: {
  filters: Filters;
  onFiltersChange: (f: Filters) => void;
  onNewIdea: () => void;
  currentUser: User;
  users: User[];
  searchRef: React.RefObject<HTMLInputElement | null>;
  onBackHome?: () => void;
  workspaceName?: string;
}) {
  const otherUser = users.find((u) => u.id !== currentUser.id && u.canAccessContent);

  const toggleStatus = (s: ContentStatus) => {
    const set = new Set(filters.status);
    if (set.has(s)) set.delete(s); else set.add(s);
    onFiltersChange({ ...filters, status: Array.from(set) });
  };

  const toggleFormat = (f: ContentFormat) => {
    const set = new Set(filters.format);
    if (set.has(f)) set.delete(f); else set.add(f);
    onFiltersChange({ ...filters, format: Array.from(set) });
  };

  return (
    <header style={{
      display: "flex", alignItems: "center", gap: 16, flexWrap: "wrap",
      padding: "14px 20px",
      background: "var(--surface)",
      borderBottom: "1px solid var(--card-border)",
    }}>
      {onBackHome && (
        <button onClick={onBackHome} title="Voltar pro app" aria-label="Voltar"
          style={{ background: "var(--input-bg)", border: "1px solid var(--card-border)", color: "var(--text)", borderRadius: 8, padding: "6px 10px", cursor: "pointer", fontSize: 12, fontFamily: "inherit" }}>
          ← App
        </button>
      )}

      <div style={{ display: "flex", flexDirection: "column", lineHeight: 1.15 }}>
        <span style={{ fontSize: 16, fontWeight: 700, color: "var(--text)", fontFamily: "var(--font-sans), Poppins, sans-serif" }}>Conteúdo</span>
        {workspaceName && (
          <span style={{ fontSize: 11, color: "var(--text-muted)", fontWeight: 600 }}>{workspaceName}</span>
        )}
      </div>

      <button onClick={onNewIdea} aria-keyshortcuts="N"
        style={{
          display: "inline-flex", alignItems: "center", gap: 6,
          background: "var(--primary)", color: "#fff", border: "none",
          padding: "8px 16px", borderRadius: 10, cursor: "pointer",
          fontSize: 13, fontWeight: 700, fontFamily: "inherit",
          boxShadow: "0 4px 14px var(--primary-ring)",
        }}>
        <Plus size={14} aria-hidden /> Nova ideia
        <span style={{ marginLeft: 4, fontSize: 10, opacity: 0.85, padding: "1px 5px", borderRadius: 4, background: "rgba(255,255,255,0.18)" }}>N</span>
      </button>

      {/* Status pills */}
      <div style={{ display: "flex", gap: 4 }}>
        {ALL_STATUSES.map((s) => {
          const active = filters.status.includes(s);
          const meta = STATUS_META[s];
          return (
            <button key={s} onClick={() => toggleStatus(s)}
              aria-pressed={active}
              style={{
                padding: "5px 11px", borderRadius: 999,
                border: `1.5px solid ${active ? meta.color : "var(--card-border)"}`,
                background: active ? `color-mix(in srgb, ${meta.color} 14%, transparent)` : "transparent",
                color: active ? meta.color : "var(--text-secondary)",
                fontSize: 11, fontWeight: 600, cursor: "pointer", fontFamily: "inherit",
              }}>
              {meta.label}
            </button>
          );
        })}
      </div>

      {/* Format icons */}
      <div style={{ display: "flex", gap: 2 }}>
        {ALL_FORMATS.map((f) => {
          const active = filters.format.includes(f);
          return (
            <button key={f} onClick={() => toggleFormat(f)}
              aria-pressed={active} title={formatLabel(f)} aria-label={formatLabel(f)}
              style={{
                width: 30, height: 30, borderRadius: 8,
                border: "1px solid var(--card-border)",
                background: active ? "var(--primary-soft)" : "transparent",
                color: active ? "var(--primary)" : "var(--text-secondary)",
                cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center",
              }}>
              <FormatIcon format={f} size={14} />
            </button>
          );
        })}
      </div>

      {/* Platform select */}
      <select value={filters.platform}
        onChange={(e) => onFiltersChange({ ...filters, platform: e.target.value as Filters["platform"] })}
        style={selectStyle}>
        <option value="all">Todas plataformas</option>
        {ALL_PLATFORMS.map((p) => <option key={p} value={p}>{PLATFORM_META[p].label}</option>)}
      </select>

      {/* Assigned filter */}
      <select value={filters.assignedTo}
        onChange={(e) => onFiltersChange({ ...filters, assignedTo: e.target.value as Filters["assignedTo"] })}
        style={selectStyle}>
        <option value="all">Todos</option>
        <option value="me">Minhas</option>
        {otherUser && <option value="other">Da {otherUser.name.split(" ")[0]}</option>}
      </select>

      {/* Busca */}
      <div style={{ position: "relative", marginLeft: "auto" }}>
