const selectStyle: React.CSSProperties = {
  background: "var(--input-bg)", border: "1px solid var(--card-border)",
  color: "var(--text)", fontSize: 12, padding: "6px 10px", borderRadius: 8,
  cursor: "pointer", fontFamily: "inherit", outline: "none",
