source:
"use client";

import { useState, useEffect, useRef, useMemo, useLayoutEffect, createContext, useContext, useCallback, CSSProperties, ReactNode } from "react";
import { createPortal } from "react-dom";
import { markdownToHtml } from "@/lib/utils";
import { exportarTarefa } from "@/lib/api";
import { DndContext, closestCenter, PointerSensor, useSensor, useSensors, DragEndEvent } from "@dnd-kit/core";
import { SortableContext, verticalListSortingStrategy, useSortable, arrayMove } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import {
  LogOut, Plus, Search, Settings, User as UserIcon,
  LayoutGrid, Trash2, KeyRound, Shield, Pencil, Eye,
  Inbox, FileText, Repeat, ListChecks, Menu as MenuIcon, X,
  Link2, LayoutDashboard, List, KanbanSquare,
  ChevronLeft, ChevronRight, PanelLeftClose, PanelLeftOpen,
  Quote, Eraser, Bell, Paperclip, Download,
} from "lucide-react";
import { api, ApiRequestError, slackApi } from "@/lib/api";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { EmptyState } from "@/components/ui/empty-state";
import { Skeleton, SkeletonList } from "@/components/ui/skeleton";
import { ShortcutsHelp } from "@/components/ui/shortcuts-help";
import { LoginScreen } from "@/components/login/login-screen";
import { DashboardView } from "@/components/dashboard/DashboardView";
import { UserAvatar } from "@/components/ui/user-avatar";
import { AvatarPicker } from "@/components/ui/avatar-picker";
import { ProfilePanel } from "@/components/profile/profile-panel";
import { KanbanBoard } from "@/components/kanban/kanban-board";
import { ContentBoard } from "@/components/content/ContentBoard";
import { VoiceCapture } from "@/components/voice/VoiceCapture";
import { TagsPicker } from "@/components/tags/tags-picker";
import type { Tag } from "@/lib/types";
import { useKeyboardShortcuts, type Shortcut } from "@/lib/use-keyboard-shortcuts";
import type {
  AppNotification,
  AssetLink,
  ChecklistItem,
  Note,
  Project,
  Role,
  RoutineCheck,
  RoutineHistoryDay,
  RoutineItem,
  Subtask,
  Task,
  TaskAttachment,
  TaskComment,
  TaskGroup,
  Transcription,
  User,
  Workspace,
} from "@/lib/types";

/** Lockup Clareza. forceWhite=true (creme) pra fundos petróleo (sidebar, hero); senão azul Egeu. */
function ClarezaLogo({ height = 28, forceWhite }: { height?: number; forceWhite?: boolean }) {
  const src = forceWhite
    ? "/logos/clareza-lockup-cream.svg"
    : "/logos/clareza-lockup-egeu.svg";
  return <img src={src} alt="Clareza" style={{ height, width: "auto", display: "block" }} />;
}

interface Group {
  id: string;
  name: string;
  color: string;
  icon: string;
  tasks: Task[];
  /** Projeto dono do grupo — usado no quick add e no drag de tarefa. */
  projectId: string;
  /** "project" = agrupado por projeto (visão Todos). "group" = task_group de verdade. */
  kind: "project" | "group";
  /** Bucket das tarefas sem grupo — não pode ser renomeado nem excluído. */
  ungrouped?: boolean;
}

const ROLES: Record<string, { label: string; color: string; icon: string; desc: string }> = {
  admin: { label: "Admin", color: "#E2445C", icon: "👑", desc: "Acesso total. Cria usuários, projetos, gerencia tudo." },
  editor: { label: "Editor", color: "#FDAB3D", icon: "✏️", desc: "Cria e edita tarefas nos projetos compartilhados." },
  viewer: { label: "Visualizador", color: "#579BFC", icon: "👁️", desc: "Apenas visualiza tarefas e projetos compartilhados." },
};

const STATUS_OPTIONS = [
  { value: "backlog", label: "Backlog", color: "#A0A0A0" },
  { value: "todo", label: "A Fazer", color: "#579BFC" },
  { value: "doing", label: "Em Progresso", color: "#FDAB3D" },
  { value: "review", label: "Revisão", color: "#E2445C" },
  { value: "done", label: "Concluído", color: "#00C875" },
];

const PRIORITY_OPTIONS = [
  { value: "high", label: "Alta", bg: "#E2445C" },      // urgente — vermelho
  { value: "medium", label: "Média", bg: "#579BFC" },   // azul
  { value: "low", label: "Baixa", bg: "#F4A8C0" },      // rosa claro
];

// Cor por prioridade (crítica legada cai em vermelho). Usada no accent do card.
const PRIORITY_COLOR: Record<string, string> = {
  critical: "#E2445C",
  high: "#E2445C",
  medium: "#579BFC",
  low: "#F4A8C0",
};
function priorityColor(p: string): string {
  return PRIORITY_COLOR[p] || "#F4A8C0";
}

const genId = () => Math.random().toString(36).slice(2, 10);

// 9 colunas: check · título · status · projeto · prazo · prioridade · pessoa · link · chevron
// 10 colunas — coluna Tarefa limitada para não esticar demais em monitores largos
// Tarefa = 1fr (fluida) pra o grid sempre caber no container; demais colunas enxutas
const GRID_COLUMNS = "24px minmax(160px, 1fr) 84px 92px 100px 76px 84px 64px 40px 64px";
const GRID_COLUMNS_SUBTASK = "24px 1fr 108px 100px 48px";

/** Estilo dos botões de ícone na régua (sidebar recolhida). */
function railBtnStyle(active: boolean): CSSProperties {
  return { width: 40, height: 40, borderRadius: 10, border: "none", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0, fontFamily: "inherit", background: active ? "var(--sidebar-active-bg)" : "transparent", color: active ? "var(--sidebar-active-text)" : "var(--sidebar-text-secondary)" };
}

/** Detecta viewport mobile (≤768px) reativo a resize/rotação. */
function useIsMobile(breakpoint = 768) {
  const [isMobile, setIsMobile] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia(`(max-width: ${breakpoint}px)`);
    const update = () => setIsMobile(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, [breakpoint]);
  return isMobile;
}

// ——— Theme ———
// Sistema é light-only. Os valores apontam pra CSS custom properties em
// globals.css; getTheme() devolve sempre o mesmo shape (compat com props).
interface Theme {
  bg: string; sidebar: string; surface: string; surfaceHover: string;
  border: string; borderStrong: string; text: string; textSecondary: string; textMuted: string;
  inputBg: string; inputBorder: string; dropdownBg: string; dropdownHover: string;
  badgeBg: (c: string) => string; badgeBorder: (c: string) => string;
  scrollThumb: string; overlay: string; scheme: "light";
  loginBg: string; cardBg: string; cardBorder: string;
}

/** Sistema é light-only. `mode` só existe pra compat — qualquer valor vira light. */
function getTheme(_mode?: unknown): Theme {
  return {
    bg: "var(--bg)",
    sidebar: "var(--sidebar)",
    surface: "var(--surface)",
    surfaceHover: "var(--surface-hover)",
    border: "var(--border)",
    borderStrong: "var(--border-strong)",
    text: "var(--text)",
    textSecondary: "var(--text-secondary)",
    textMuted: "var(--text-muted)",
    inputBg: "var(--input-bg)",
    inputBorder: "var(--input-border)",
    dropdownBg: "var(--dropdown-bg)",
    dropdownHover: "var(--dropdown-hover)",
    badgeBg: (c: string) => c + "15",
    badgeBorder: (c: string) => c + "30",
    scrollThumb: "var(--scroll-thumb)",
    overlay: "var(--overlay)",
    scheme: "light",
    loginBg: "var(--bg)",
    cardBg: "var(--surface)",
