            </>
          )}

          {tab === "tags" && (
            <TagsManagement tags={tags} onUpdate={onUpdateTags} theme={theme} />
          )}

          {tab === "slack" && (
            <SlackChannels projects={projects} workspaces={workspaces} theme={theme} />
          )}
