  const hasContent = !!user.canAccessContent;

  return (
    <div style={{
      display: "flex", alignItems: "center", gap: 12, padding: "12px 16px",
      borderRadius: 12, border: `1px solid ${theme.border}`, marginBottom: 6,
      background: isMe ? theme.badgeBg("var(--primary)") : "transparent"
    }}>
      <button
        onClick={() => setShowAvatarPicker(true)}
        aria-label={`Editar avatar de ${user.name}`}
        title="Trocar avatar"
        style={{ background: "transparent", border: "none", padding: 0, cursor: "pointer", borderRadius: "50%" }}
      >
        <UserAvatar avatar={user.avatar} name={user.name} size={36} />
      </button>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: 14, fontWeight: 600, color: theme.text }}>
          {user.name} {isMe && <span style={{ fontSize: 10, color: "var(--primary)" }}>(você)</span>}
        </div>
        <div style={{ fontSize: 12, color: theme.textMuted }}>@{user.username}</div>
      </div>

      <select value={user.role} onChange={(e) => onChangeRole(e.target.value as Role)} disabled={isMe}
        style={{
          background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 8,
          padding: "5px 8px", color: role.color, fontSize: 12, fontWeight: 600, outline: "none",
          cursor: isMe ? "default" : "pointer", colorScheme: theme.scheme, fontFamily: "inherit"
        }}>
        {Object.entries(ROLES).map(([k, v]) => <option key={k} value={k}>{v.icon} {v.label}</option>)}
      </select>

      <button
        onClick={() => onToggleContentAccess(!hasContent)}
        title={hasContent ? "Remover acesso ao Hub de Conteúdo" : "Liberar acesso ao Hub de Conteúdo"}
        aria-pressed={hasContent}
        style={{
          background: hasContent ? "var(--primary-soft)" : theme.inputBg,
          border: `1px solid ${hasContent ? "var(--primary)" : theme.border}`,
          borderRadius: 8, padding: "5px 10px",
          color: hasContent ? "var(--primary)" : theme.textSecondary,
          cursor: "pointer", fontSize: 11, fontWeight: 700, fontFamily: "inherit",
          display: "inline-flex", alignItems: "center", gap: 5,
        }}>
        <FileText size={11} aria-hidden /> Conteúdo {hasContent ? "✓" : "○"}
      </button>

      {showReset ? (
        <div style={{ display: "flex", gap: 4 }}>
          <input value={newPwd} onChange={(e) => setNewPwd(e.target.value)} placeholder="Nova senha"
            style={{ background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 6, padding: "5px 8px", color: theme.text, fontSize: 12, outline: "none", width: 120, fontFamily: "inherit" }} />
          <button onClick={() => { if (newPwd.trim()) { onResetPassword(newPwd); setShowReset(false); setNewPwd(""); } }}
            style={{ background: "#00C875", border: "none", color: "#fff", borderRadius: 6, padding: "5px 10px", cursor: "pointer", fontSize: 11, fontWeight: 700 }}>✓</button>
          <button onClick={() => setShowReset(false)}
            style={{ background: theme.inputBg, border: "none", color: theme.textMuted, borderRadius: 6, padding: "5px 8px", cursor: "pointer", fontSize: 11 }}>✕</button>
        </div>
      ) : (
        <button onClick={() => setShowReset(true)}
          style={{ background: theme.inputBg, border: `1px solid ${theme.border}`, borderRadius: 8, padding: "5px 12px", color: theme.textSecondary, cursor: "pointer", fontSize: 11, fontWeight: 600, fontFamily: "inherit" }}>
          🔑 Reset
        </button>
      )}

      {!isMe && (
        <button onClick={onDelete}
          style={{ background: "rgba(226,68,92,0.1)", border: "1px solid rgba(226,68,92,0.2)", borderRadius: 8, padding: "5px 10px", color: "#E2445C", cursor: "pointer", fontSize: 11, fontWeight: 600 }}>
          🗑️
        </button>
      )}

      <AvatarPicker
        open={showAvatarPicker}
        currentAvatar={user.avatar}
        userName={user.name}
        onCancel={() => setShowAvatarPicker(false)}
        onSelect={(seed) => { onChangeAvatar(seed); setShowAvatarPicker(false); }}
      />
    </div>
  );
}

// ——— Rich Text Editor (Monday.com style) ———
function RichEditor({ value, onChange, theme, readOnly, placeholder, users, onMention }: { value: string; onChange: (v: string) => void; theme: Theme; readOnly?: boolean; placeholder?: string; users?: User[]; onMention?: (userId: string) => void }) {
  const editorRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const isInitialMount = useRef(true);
  const [showMentions, setShowMentions] = useState(false);
  const [mentionPos, setMentionPos] = useState<{ top: number; left: number } | null>(null);
  const [mentionQuery, setMentionQuery] = useState("");

  const toggleMentions = () => {
    editorRef.current?.focus();
    if (showMentions) { setShowMentions(false); return; }
    const r = containerRef.current?.getBoundingClientRect();
    if (r) setMentionPos({ top: r.top + 46, left: r.left + 10 });
    setMentionQuery("");
    setShowMentions(true);
  };

  useEffect(() => {
    if (editorRef.current && isInitialMount.current) {
      editorRef.current.innerHTML = value || "";
      isInitialMount.current = false;
    }
  }, [value]);

  const exec = (cmd: string, val?: string) => {
    editorRef.current?.focus();
    document.execCommand(cmd, false, val);
    if (editorRef.current) onChange(editorRef.current.innerHTML);
  };

  const handleInput = () => {
    const el = editorRef.current;
    if (!el) return;
    // Atalho markdown: uma linha com exatamente "---" vira divisória
    const sel = window.getSelection();
    if (sel && sel.anchorNode && sel.anchorNode.nodeType === 3) {
      const tn = sel.anchorNode as Text;
      if (tn.textContent === "---") {
        tn.textContent = "";
        document.execCommand("insertHorizontalRule");
      }
    }
    onChange(el.innerHTML);
  };

  // Colar limpo: descarta o HTML da origem, mas entende o markdown que
  // ChatGPT/Claude/Gemini produzem — títulos, listas, negrito e links viram
  // formatação de verdade em vez de "###" e "**" no meio do texto.
  const handlePaste = (e: React.ClipboardEvent<HTMLDivElement>) => {
    e.preventDefault();
    const text = e.clipboardData.getData("text/plain");
    if (!text) return;
    const looksLikeMarkdown = /(^|\n)\s*(#{1,6}\s|[-*•]\s|\d+[.)]\s|>\s)|\*\*[^*]+\*\*/.test(text);
    const multiline = text.includes("\n");
    if (looksLikeMarkdown || multiline) {
      document.execCommand("insertHTML", false, markdownToHtml(text));
    } else {
      document.execCommand("insertText", false, text);
    }
    if (editorRef.current) onChange(editorRef.current.innerHTML);
  };

  const insertLink = () => {
    let url = window.prompt("URL do link:");
    if (!url) return;
    url = url.trim();
    if (!/^https?:\/\//i.test(url) && !url.startsWith("mailto:")) url = "https://" + url;
    exec("createLink", url);
  };

  const insertMention = (u: User) => {
    editorRef.current?.focus();
    const first = u.name.split(" ")[0];
    const html = `<span class="rt-mention" data-user-id="${u.id}">@${first}</span>&nbsp;`;
    document.execCommand("insertHTML", false, html);
    setShowMentions(false);
    setMentionQuery("");
    if (editorRef.current) onChange(editorRef.current.innerHTML);
    onMention?.(u.id);
  };

  const mentionableUsers = (users || []).filter((u) =>
    !mentionQuery || u.name.toLowerCase().includes(mentionQuery.toLowerCase())
  );

  const toolBtn = (label: ReactNode, action: () => void, title: string, opts?: { bold?: boolean; italic?: boolean; strike?: boolean }) => (
    <button onClick={action} title={title} type="button"
      onMouseDown={(e) => e.preventDefault()}
      style={{ background: "none", border: "none", cursor: "pointer", padding: "4px 8px", borderRadius: 4, color: theme.textSecondary, fontSize: 13, fontWeight: opts?.bold ? 700 : 600, fontStyle: opts?.italic ? "italic" : "normal", textDecoration: opts?.strike ? "line-through" : "none", fontFamily: "inherit", lineHeight: 1, display: "flex", alignItems: "center", justifyContent: "center", minWidth: 28, height: 28 }}
      onMouseEnter={(e) => { e.currentTarget.style.background = theme.surfaceHover; e.currentTarget.style.color = theme.text; }}
      onMouseLeave={(e) => { e.currentTarget.style.background = "none"; e.currentTarget.style.color = theme.textSecondary; }}>
      {label}
    </button>
  );

  const sep = () => <div style={{ width: 1, height: 18, background: theme.border, margin: "0 3px" }} />;

  return (
    <div ref={containerRef} style={{ border: `1px solid ${theme.border}`, borderRadius: 8, overflow: "visible", position: "relative" }}>
      {!readOnly && (
        <div style={{ display: "flex", alignItems: "center", gap: 1, flexWrap: "wrap", padding: "6px 10px", borderBottom: `1px solid ${theme.border}`, background: theme.inputBg }}>
          {toolBtn("B", () => exec("bold"), "Negrito", { bold: true })}
          {toolBtn("I", () => exec("italic"), "Itálico", { italic: true })}
          {toolBtn("U", () => exec("underline"), "Sublinhado")}
          {toolBtn("S", () => exec("strikeThrough"), "Tachado", { strike: true })}
          {sep()}
          {toolBtn("H2", () => exec("formatBlock", "h2"), "Título")}
          {toolBtn("H3", () => exec("formatBlock", "h3"), "Subtítulo")}
          {sep()}
          {toolBtn(<List size={15} />, () => exec("insertUnorderedList"), "Lista")}
          {toolBtn(<ListChecks size={15} />, () => exec("insertOrderedList"), "Lista numerada")}
          {toolBtn(<Quote size={15} />, () => exec("formatBlock", "blockquote"), "Citação")}
          {sep()}
          {toolBtn(<Link2 size={15} />, insertLink, "Inserir link")}
          {toolBtn("@", toggleMentions, "Mencionar (notifica no sistema)")}
          {toolBtn("―", () => exec("insertHorizontalRule"), "Divisória (ou digite ---)")}
          {sep()}
          {toolBtn(<Eraser size={15} />, () => exec("removeFormat"), "Limpar formatação")}
        </div>
      )}

      {showMentions && !readOnly && mentionPos && createPortal(
        <>
          <div onMouseDown={() => setShowMentions(false)} style={{ position: "fixed", inset: 0, zIndex: 1290 }} />
          <div style={{ position: "fixed", zIndex: 1300, top: mentionPos.top, left: mentionPos.left, width: 240, background: theme.dropdownBg, border: `1px solid ${theme.border}`, borderRadius: 10, boxShadow: "0 8px 28px var(--card-shadow-color, rgba(15,76,92,0.20))", overflow: "hidden" }}
            onMouseDown={(e) => e.preventDefault()}>
            <input autoFocus value={mentionQuery} onChange={(e) => setMentionQuery(e.target.value)}
              placeholder="Mencionar quem…"
              style={{ width: "100%", border: "none", borderBottom: `1px solid ${theme.border}`, padding: "9px 12px", fontSize: 13, outline: "none", background: "transparent", color: theme.text, fontFamily: "inherit" }} />
            <div style={{ maxHeight: 200, overflowY: "auto" }}>
              {mentionableUsers.length === 0 ? (
                <div style={{ padding: "10px 12px", fontSize: 12, color: theme.textMuted }}>Ninguém encontrado</div>
              ) : mentionableUsers.map((u) => (
                <button key={u.id} type="button" onClick={() => insertMention(u)}
                  style={{ display: "flex", alignItems: "center", gap: 8, width: "100%", border: "none", background: "transparent", padding: "8px 12px", cursor: "pointer", textAlign: "left", fontFamily: "inherit", color: theme.text }}
                  onMouseEnter={(e) => (e.currentTarget.style.background = theme.surfaceHover)}
                  onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}>
                  <UserAvatar avatar={u.avatar} name={u.name} size={22} background="var(--primary-soft)" />
                  <span style={{ fontSize: 13 }}>{u.name}</span>
                </button>
              ))}
            </div>
          </div>
        </>,
        document.body
      )}

      <div
        ref={editorRef}
        contentEditable={!readOnly}
        suppressContentEditableWarning
        onInput={handleInput}
        onPaste={handlePaste}
        data-placeholder={placeholder}
        style={{
          padding: "14px 16px", minHeight: 120, outline: "none", color: theme.text,
          fontSize: 14, lineHeight: 1.7, fontFamily: "inherit",
          overflowY: "auto", maxHeight: 400, cursor: readOnly ? "default" : "text",
        }}
      />
      <style>{`
        [data-placeholder]:empty:before { content: attr(data-placeholder); color: ${theme.textMuted}; pointer-events: none; }
        [contenteditable] a { color: var(--primary-hover); text-decoration: underline; }
        [contenteditable] h2 { font-size: 18px; font-weight: 700; margin: 10px 0 4px; }
        [contenteditable] h3 { font-size: 15px; font-weight: 700; margin: 8px 0 4px; }
        [contenteditable] h4 { font-size: 14px; font-weight: 700; margin: 8px 0 4px; }
        [contenteditable] p { margin: 0 0 8px; }
        [contenteditable] code { font-family: var(--font-mono, monospace); font-size: 13px; background: var(--primary-soft); padding: 1px 5px; border-radius: 4px; }
        [contenteditable] ul, [contenteditable] ol { margin: 6px 0 6px 22px; }
        [contenteditable] li { margin: 2px 0; }
        [contenteditable] blockquote { margin: 8px 0; padding: 6px 14px; border-left: 3px solid var(--primary); background: var(--primary-soft); color: var(--text-secondary); border-radius: 0 6px 6px 0; }
        [contenteditable] hr { border: none; border-top: 1px solid ${theme.border}; margin: 12px 0; }
        .rt-mention { color: var(--primary-hover); font-weight: 600; background: var(--primary-soft); padding: 0 4px; border-radius: 4px; }
      `}</style>
    </div>
  );
}

// ——— Assets (links de drives por workspace) ———
function AssetsView({ theme }: { theme: Theme }) {
  const [items, setItems] = useState<AssetLink[]>([]);
  const [loading, setLoading] = useState(true);
  const [adding, setAdding] = useState(false);
  const [title, setTitle] = useState("");
  const [url, setUrl] = useState("");
  const [desc, setDesc] = useState("");
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try { setItems(await api.getAssets()); } catch { /* noop */ } finally { setLoading(false); }
  }, []);
  useEffect(() => { load(); }, [load]);

  const add = async () => {
    if (!title.trim() || !url.trim()) return;
    setSaving(true);
    try {
      const a = await api.createAsset({ title: title.trim(), url: url.trim(), description: desc.trim() || undefined });
      setItems((prev) => [...prev, a]);
      setTitle(""); setUrl(""); setDesc(""); setAdding(false);
    } catch (err) {
      alert(err instanceof Error ? err.message : "Falha ao salvar");
    } finally { setSaving(false); }
  };

  const remove = async (id: string) => {
    if (!window.confirm("Remover este link?")) return;
    setItems((prev) => prev.filter((a) => a.id !== id));
    try { await api.deleteAsset(id); } catch { load(); }
  };

  const hostOf = (u: string) => { try { return new URL(u.startsWith("http") ? u : "https://" + u).hostname.replace("www.", ""); } catch { return u; } };
  const openLink = (u: string) => window.open(u.startsWith("http") ? u : "https://" + u, "_blank", "noopener");

  return (
    <div style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
      <div style={{ padding: "12px 24px", borderBottom: `1px solid ${theme.border}`, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
        <p style={{ fontSize: 13, color: theme.textMuted, margin: 0 }}>Links e drives da empresa</p>
        <button onClick={() => setAdding((s) => !s)}
          style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "var(--primary)", color: "#fff", border: "none", borderRadius: 10, padding: "9px 16px", fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
          <Plus size={14} aria-hidden /> Novo link
        </button>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: 24 }}>
        {adding && (
          <div style={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 12, padding: 16, marginBottom: 16, maxWidth: 640, display: "flex", flexDirection: "column", gap: 10 }}>
            <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Nome (ex: Drive de Marketing)" autoFocus
              style={{ padding: "9px 12px", background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 8, color: theme.text, fontSize: 14, outline: "none", fontFamily: "inherit" }} />
            <input value={url} onChange={(e) => setUrl(e.target.value)} placeholder="Link (https://drive.google.com/...)" onKeyDown={(e) => e.key === "Enter" && add()}
              style={{ padding: "9px 12px", background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 8, color: theme.text, fontSize: 14, outline: "none", fontFamily: "inherit" }} />
            <input value={desc} onChange={(e) => setDesc(e.target.value)} placeholder="Descrição (opcional)"
              style={{ padding: "9px 12px", background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 8, color: theme.text, fontSize: 13, outline: "none", fontFamily: "inherit" }} />
            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={add} disabled={saving || !title.trim() || !url.trim()}
                style={{ background: "var(--primary)", color: "#fff", border: "none", borderRadius: 8, padding: "8px 16px", fontSize: 13, fontWeight: 700, cursor: "pointer", opacity: (saving || !title.trim() || !url.trim()) ? 0.5 : 1, fontFamily: "inherit" }}>
                {saving ? "Salvando…" : "Salvar"}
              </button>
              <button onClick={() => setAdding(false)} style={{ background: theme.inputBg, color: theme.textSecondary, border: `1px solid ${theme.border}`, borderRadius: 8, padding: "8px 14px", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>Cancelar</button>
            </div>
          </div>
        )}

        {loading ? (
          <div style={{ color: theme.textMuted, fontSize: 14 }}>Carregando…</div>
        ) : items.length === 0 ? (
          <EmptyState icon={Link2} title="Nenhum link ainda" description="Adicione os drives e recursos deste workspace pra acesso rápido." />
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))", gap: 12 }}>
            {items.map((a) => (
              <div key={a.id} style={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: 12, padding: 16, display: "flex", flexDirection: "column", gap: 6, position: "relative" }}>
                <button onClick={() => remove(a.id)} title="Remover" aria-label="Remover"
                  style={{ position: "absolute", top: 10, right: 10, background: "none", border: "none", color: theme.textMuted, cursor: "pointer", padding: 4, borderRadius: 6 }}>
                  <Trash2 size={14} />
                </button>
                <button onClick={() => openLink(a.url)} style={{ textAlign: "left", background: "none", border: "none", cursor: "pointer", padding: 0, fontFamily: "inherit", display: "flex", alignItems: "center", gap: 8 }}>
                  <span style={{ width: 32, height: 32, borderRadius: 8, background: "var(--primary-soft)", color: "var(--primary)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Link2 size={16} /></span>
                  <span style={{ fontSize: 14, fontWeight: 700, color: theme.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{a.title}</span>
                </button>
                {a.description && <p style={{ fontSize: 12, color: theme.textSecondary, margin: 0, lineHeight: 1.45 }}>{a.description}</p>}
                <button onClick={() => openLink(a.url)} style={{ textAlign: "left", background: "none", border: "none", cursor: "pointer", padding: 0, fontFamily: "inherit", fontSize: 11, color: "var(--primary-hover)", display: "inline-flex", alignItems: "center", gap: 4 }}>
                  {hostOf(a.url)} <Link2 size={11} />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ——— Sininho de notificações internas ———
function relTimeShort(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return "agora";
  if (m < 60) return `${m}min`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h`;
  const d = Math.floor(h / 24);
  return `${d}d`;
}

function NotificationBell({ theme, onOpenTask }: { theme: Theme; onOpenTask: (taskId: string) => void }) {
  const [items, setItems] = useState<AppNotification[]>([]);
  const [unread, setUnread] = useState(0);
  const [open, setOpen] = useState(false);
  const wrapRef = useRef<HTMLDivElement>(null);

  const load = useCallback(async () => {
    try {
      const r = await api.getNotifications();
      setItems(r.items);
      setUnread(r.unread);
    } catch { /* silencioso */ }
  }, []);

  useEffect(() => {
    load();
    const t = setInterval(load, 30000);
    return () => clearInterval(t);
  }, [load]);

  useEffect(() => {
    const onDoc = (e: MouseEvent) => { if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false); };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  const markAll = async () => {
    setItems((prev) => prev.map((n) => ({ ...n, read: true })));
    setUnread(0);
    try { await api.markNotificationsRead(); } catch { /* noop */ }
  };

  const openNotif = async (n: AppNotification) => {
    setOpen(false);
    if (!n.read) {
      setItems((prev) => prev.map((x) => (x.id === n.id ? { ...x, read: true } : x)));
      setUnread((u) => Math.max(0, u - 1));
      api.markNotificationsRead([n.id]).catch(() => {});
    }
    if (n.taskId) onOpenTask(n.taskId);
  };

  return (
    <div ref={wrapRef} style={{ position: "relative" }}>
      <button onClick={() => setOpen((s) => !s)} aria-label="Notificações" title="Notificações"
        className="topbar-icon-btn"
        style={{ position: "relative", background: theme.inputBg, border: `1px solid ${theme.border}`, color: theme.textSecondary, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", width: 36, height: 36, borderRadius: 8 }}>
        <Bell size={16} />
        {unread > 0 && (
          <span style={{ position: "absolute", top: -5, right: -5, minWidth: 17, height: 17, padding: "0 4px", borderRadius: 9, background: "#E2445C", color: "#fff", fontSize: 10, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", border: `2px solid ${theme.surface}` }}>
            {unread > 9 ? "9+" : unread}
          </span>
        )}
      </button>

      {open && (
        <div style={{ position: "absolute", top: 44, right: 0, width: "min(340px, 92vw)", background: theme.dropdownBg, border: `1px solid ${theme.border}`, borderRadius: 12, boxShadow: "0 12px 40px rgba(0,0,0,0.18)", zIndex: 1200, overflow: "hidden" }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 14px", borderBottom: `1px solid ${theme.border}` }}>
            <span style={{ fontSize: 13, fontWeight: 700, color: theme.text }}>Notificações</span>
            {unread > 0 && (
              <button onClick={markAll} style={{ background: "none", border: "none", color: "var(--primary)", cursor: "pointer", fontSize: 12, fontWeight: 600, fontFamily: "inherit" }}>
                Marcar todas como lidas
              </button>
            )}
          </div>
          <div style={{ maxHeight: 360, overflowY: "auto" }}>
            {items.length === 0 ? (
              <div style={{ padding: "28px 16px", textAlign: "center", color: theme.textMuted, fontSize: 13 }}>Sem notificações por aqui.</div>
            ) : items.map((n) => (
              <button key={n.id} onClick={() => openNotif(n)}
                style={{ display: "flex", gap: 10, width: "100%", border: "none", borderBottom: `1px solid ${theme.border}`, background: n.read ? "transparent" : "var(--primary-soft)", padding: "11px 14px", cursor: "pointer", textAlign: "left", fontFamily: "inherit" }}
                onMouseEnter={(e) => (e.currentTarget.style.background = theme.surfaceHover)}
                onMouseLeave={(e) => (e.currentTarget.style.background = n.read ? "transparent" : "var(--primary-soft)")}>
                <span style={{ marginTop: 2, color: "var(--primary)", flexShrink: 0 }}><Bell size={15} /></span>
                <span style={{ flex: 1, minWidth: 0 }}>
                  <span style={{ display: "block", fontSize: 13, color: theme.text, lineHeight: 1.4 }}>{n.title}</span>
                  <span style={{ fontSize: 11, color: theme.textMuted }}>{relTimeShort(n.createdAt)}</span>
                </span>
                {!n.read && <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#E2445C", flexShrink: 0, marginTop: 5 }} />}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ——— Task Detail (Monday.com style — tela única) ———
interface TaskDetailProps {
  task: Task;
  projects: Project[];
  users: User[];
  tags: Tag[];
  onUpdate: (task: Task) => void;
  onClose: () => void;
  theme: Theme;
  canEdit: boolean;
}

function DrawerField({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div>
      <div style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.4, color: "var(--text-muted)", marginBottom: 6 }}>{label}</div>
      {children}
    </div>
  );
}

function TaskDetail({ task, projects, users, tags, onUpdate, onClose, theme, canEdit }: TaskDetailProps) {
  const [newCheckItem, setNewCheckItem] = useState("");
  const checkInputRef = useRef<HTMLInputElement>(null);
  const assignee = users?.find((u) => u.id === task.assignedTo);
  const project = projects.find((p) => p.id === task.projectId);
  const checkDone = (task.checklist || []).filter((i) => i.done).length;
  const checkTotal = (task.checklist || []).length;
  const checkPct = checkTotal ? Math.round((checkDone / checkTotal) * 100) : 0;

  const addCheckItem = () => {
    if (!newCheckItem.trim() || !canEdit) return;
    onUpdate({ ...task, checklist: [...(task.checklist || []), { id: genId(), text: newCheckItem.trim(), done: false }] });
    setNewCheckItem("");
    setTimeout(() => checkInputRef.current?.focus(), 50);
  };

  return (
    <div role="dialog" aria-modal="true" aria-label={`Detalhes da tarefa: ${task.title}`} style={{ position: "fixed", inset: 0, zIndex: 1000, display: "flex", justifyContent: "flex-end" }} onClick={onClose}>
      <div style={{ position: "absolute", inset: 0, background: theme.overlay, backdropFilter: "blur(4px)" }} />
      <div onClick={(e) => e.stopPropagation()} className="task-drawer" style={{
        position: "relative", width: "min(640px, 94vw)", height: "100%",
        background: theme.surface, display: "flex", flexDirection: "column",
        boxShadow: "-8px 0 40px rgba(0,0,0,0.15)", animation: "slideIn 0.25s ease-out"
      }}>
        {/* Header */}
        <div style={{ padding: "20px 24px", flexShrink: 0, borderBottom: `1px solid ${theme.border}` }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <button onClick={onClose} style={{ background: "none", border: "none", color: theme.textSecondary, cursor: "pointer", fontSize: 20, padding: 4, display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 4, flexShrink: 0 }}
              onMouseEnter={(e) => e.currentTarget.style.background = theme.surfaceHover}
              onMouseLeave={(e) => e.currentTarget.style.background = "none"}>✕</button>
            <input value={task.title}
              onChange={(e) => canEdit && onUpdate({ ...task, title: e.target.value })}
              onBlur={(e) => { if (canEdit && !e.target.value.trim()) onUpdate({ ...task, title: "Nova tarefa" }); }}
              readOnly={!canEdit}
              style={{ flex: 1, background: "transparent", border: "none", color: theme.text, fontSize: 24, fontWeight: 700, outline: "none", fontFamily: "inherit", padding: 0, letterSpacing: -0.1, cursor: canEdit ? "text" : "default" }} />
            <div style={{ display: "flex", alignItems: "center", gap: 8, flexShrink: 0 }}>
              <button onClick={() => {
                  const url = `${window.location.origin}/?tarefa=${task.id}`;
                  navigator.clipboard?.writeText(url);
                }}
                title="Copiar link da tarefa"
                style={{ display: "inline-flex", alignItems: "center", gap: 6, background: theme.inputBg, border: `1px solid ${theme.border}`, color: theme.textSecondary, borderRadius: 8, padding: "6px 12px", cursor: "pointer", fontSize: 12, fontWeight: 600, fontFamily: "inherit" }}>
                <Link2 size={14} aria-hidden /> Copiar link
              </button>
              <button onClick={() => exportarTarefa(task.id)}
                title="Exportar conteúdo em PDF"
                style={{ display: "inline-flex", alignItems: "center", gap: 6, background: theme.inputBg, border: `1px solid ${theme.border}`, color: theme.textSecondary, borderRadius: 8, padding: "6px 12px", cursor: "pointer", fontSize: 12, fontWeight: 600, fontFamily: "inherit" }}>
                <FileText size={14} aria-hidden /> Exportar
              </button>
              {assignee && (
                <div title={assignee.name} style={{ width: 34, height: 34, borderRadius: "50%", background: theme.badgeBg("#579BFC"), display: "flex", alignItems: "center", justifyContent: "center", fontSize: 17, border: `2px solid ${theme.border}` }}>
                  {assignee.avatar}
                </div>
              )}
              {project && (
                <span style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 12, color: project.color, fontWeight: 600, background: theme.badgeBg(project.color), padding: "3px 10px", borderRadius: 12 }}>
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><span style={{ width: 9, height: 9, borderRadius: "50%", background: project.color, flexShrink: 0 }} />{project.name}</span>
                </span>
              )}
            </div>
          </div>
        </div>

        {/* Content */}
        <div style={{ flex: 1, overflowY: "auto", padding: "24px 24px 32px" }}>
          {!canEdit && (
            <div style={{ padding: "8px 14px", borderRadius: 8, background: "rgba(87,155,252,0.1)", border: "1px solid rgba(87,155,252,0.2)", color: "#579BFC", fontSize: 13, fontWeight: 500, marginBottom: 20, display: "flex", alignItems: "center", gap: 8 }}>
              <span>👁️</span> Modo visualização
            </div>
          )}

          {/* Rich text description */}
          <RichEditor
            value={task.description || ""}
            onChange={(v) => canEdit && onUpdate({ ...task, description: v })}
            theme={theme}
            readOnly={!canEdit}
            placeholder={canEdit ? "Escreva aqui... Use a barra de ferramentas para formatar" : "Sem descrição"}
            users={users}
            onMention={(userId) => { api.notifyMention(task.id, userId).catch(() => {}); }}
          />

          {/* Meta: timeline + estimativa + tags */}
          <div style={{ marginTop: 28, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 18 }}>
            <DrawerField label="Início">
              <input
                type="date"
                value={task.startDate || ""}
                readOnly={!canEdit}
                onChange={(e) => canEdit && onUpdate({ ...task, startDate: e.target.value })}
                style={{ width: "100%", background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 8, padding: "8px 12px", color: theme.text, fontSize: 13, outline: "none", colorScheme: theme.scheme, fontFamily: "inherit" }}
              />
            </DrawerField>
            <DrawerField label="Prazo">
              <input
                type="date"
                value={task.deadline || ""}
                readOnly={!canEdit}
                onChange={(e) => canEdit && onUpdate({ ...task, deadline: e.target.value })}
                style={{ width: "100%", background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 8, padding: "8px 12px", color: theme.text, fontSize: 13, outline: "none", colorScheme: theme.scheme, fontFamily: "inherit" }}
              />
            </DrawerField>
            <DrawerField label="Estimativa (horas)">
              <input
                type="number"
                step="0.25"
                min="0"
                value={task.estimateHours ?? ""}
                readOnly={!canEdit}
                onChange={(e) => {
                  if (!canEdit) return;
                  const v = e.target.value;
                  onUpdate({ ...task, estimateHours: v === "" ? null : parseFloat(v) });
                }}
                placeholder="Ex: 2.5"
                style={{ width: "100%", background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 8, padding: "8px 12px", color: theme.text, fontSize: 13, outline: "none", fontFamily: "inherit" }}
              />
            </DrawerField>
            <DrawerField label="Etiquetas">
              <div style={{ background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 8, padding: "8px 12px", minHeight: 38, display: "flex", alignItems: "center" }}>
                <TagsPicker
                  allTags={tags}
                  selectedIds={task.tagIds || []}
                  onChange={(ids) => canEdit && onUpdate({ ...task, tagIds: ids })}
                  disabled={!canEdit}
                  variant="full"
                />
              </div>
            </DrawerField>
          </div>

          {/* Checklist — simple Monday.com style */}
          <div style={{ marginTop: 28 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
              <span style={{ fontSize: 14, fontWeight: 600, color: theme.text }}>Checklist</span>
              {checkTotal > 0 && (
                <>
                  <span style={{ fontSize: 12, color: theme.textMuted }}>{checkDone}/{checkTotal}</span>
                  <div style={{ flex: 1, height: 4, borderRadius: 4, background: theme.inputBg, maxWidth: 120 }}>
                    <div style={{ width: checkPct + "%", height: "100%", borderRadius: 4, background: "#00C875", transition: "width 0.3s" }} />
                  </div>
                </>
              )}
            </div>

            {(task.checklist || []).map((item) => (
              <div key={item.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 0", borderBottom: `1px solid ${theme.border}` }}>
                <button onClick={() => canEdit && onUpdate({ ...task, checklist: task.checklist.map((i) => i.id === item.id ? { ...i, done: !i.done } : i) })}
                  style={{ width: 18, height: 18, borderRadius: 4, border: `2px solid ${item.done ? "#00C875" : theme.textMuted}`, background: item.done ? "#00C875" : "transparent", cursor: canEdit ? "pointer" : "default", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, padding: 0, transition: "all 0.15s" }}>
                  {item.done && <span style={{ color: "#fff", fontSize: 11, fontWeight: 700 }}>✓</span>}
                </button>
                <span style={{ flex: 1, fontSize: 14, color: item.done ? theme.textMuted : theme.text, textDecoration: item.done ? "line-through" : "none", transition: "all 0.15s" }}>{item.text}</span>
                {canEdit && <button onClick={() => onUpdate({ ...task, checklist: task.checklist.filter((i) => i.id !== item.id) })}
                  style={{ background: "none", border: "none", color: theme.textMuted, cursor: "pointer", fontSize: 16, padding: "0 4px", opacity: 0.4, transition: "opacity 0.15s" }}
                  onMouseEnter={(e) => e.currentTarget.style.opacity = "1"}
                  onMouseLeave={(e) => e.currentTarget.style.opacity = "0.4"}>×</button>}
              </div>
            ))}

            {canEdit && (
              <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 0" }}>
                <div style={{ width: 18, height: 18, borderRadius: 4, border: `2px dashed ${theme.textMuted}`, opacity: 0.4, flexShrink: 0 }} />
                <input ref={checkInputRef} value={newCheckItem} onChange={(e) => setNewCheckItem(e.target.value)}
                  onKeyDown={(e) => { if (e.key === "Enter") addCheckItem(); }}
                  placeholder="Adicionar item..."
                  style={{ flex: 1, background: "transparent", border: "none", color: theme.text, fontSize: 14, outline: "none", fontFamily: "inherit", padding: 0 }} />
              </div>
            )}
          </div>

          {/* Subtarefas — bloco separado abaixo do checklist */}
          <SubtasksBlock task={task} canEdit={canEdit} theme={theme} onUpdate={onUpdate} />

          <AttachmentsBlock taskId={task.id} theme={theme} />

          <TaskComments taskId={task.id} users={users} theme={theme} canEdit={canEdit} />
        </div>
      </div>
    </div>
  );
}

// ——— Subtasks Block (dentro do TaskDetail) ———
function SubtasksBlock({ task, canEdit, theme, onUpdate }: { task: Task; canEdit: boolean; theme: Theme; onUpdate: (t: Task) => void }) {
  const [newTitle, setNewTitle] = useState("");
  const subtasks = task.subtasks || [];
  const stDone = subtasks.filter((s) => s.checked).length;
  const stTotal = subtasks.length;
  const stPct = stTotal ? Math.round((stDone / stTotal) * 100) : 0;

  const addSubtask = () => {
    const title = newTitle.trim();
    if (!title || !canEdit) return;
    onUpdate({ ...task, subtasks: [...subtasks, { id: genId(), title, status: "todo", checked: false }] });
    setNewTitle("");
  };

  const toggle = (id: string) => {
    if (!canEdit) return;
    onUpdate({ ...task, subtasks: subtasks.map((s) => s.id === id ? { ...s, checked: !s.checked, status: !s.checked ? "done" : "todo" } : s) });
  };

  const updateTitle = (id: string, title: string) => {
    if (!canEdit) return;
    onUpdate({ ...task, subtasks: subtasks.map((s) => s.id === id ? { ...s, title } : s) });
  };

  const updateStatus = (id: string, status: string) => {
    if (!canEdit) return;
    onUpdate({ ...task, subtasks: subtasks.map((s) => s.id === id ? { ...s, status, checked: status === "done" } : s) });
  };

  const remove = (id: string) => {
    if (!canEdit) return;
    onUpdate({ ...task, subtasks: subtasks.filter((s) => s.id !== id) });
  };

  return (
    <div style={{ marginTop: 28 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
        <span style={{ fontSize: 14, fontWeight: 600, color: theme.text }}>Subtarefas</span>
        {stTotal > 0 && (
          <>
            <span style={{ fontSize: 12, color: theme.textMuted }}>{stDone}/{stTotal}</span>
            <div style={{ flex: 1, height: 4, borderRadius: 4, background: theme.inputBg, maxWidth: 120 }}>
              <div style={{ width: stPct + "%", height: "100%", borderRadius: 4, background: "var(--status-done)", transition: "width 0.3s" }} />
            </div>
          </>
        )}
      </div>

      {subtasks.map((st) => (
        <div key={st.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 0", borderBottom: `1px solid ${theme.border}` }}>
          <button
            onClick={() => toggle(st.id)}
            aria-label={st.checked ? "Desmarcar subtarefa" : "Marcar como concluída"}
            disabled={!canEdit}
            style={{
              width: 18, height: 18, borderRadius: 4,
              border: `2px solid ${st.checked ? "var(--status-done)" : theme.textMuted}`,
              background: st.checked ? "var(--status-done)" : "transparent",
              cursor: canEdit ? "pointer" : "default",
              display: "flex", alignItems: "center", justifyContent: "center",
              flexShrink: 0, padding: 0,
            }}
          >
            {st.checked && <span style={{ color: "#fff", fontSize: 11, fontWeight: 700 }}>✓</span>}
          </button>
          <input
            value={st.title}
            onChange={(e) => updateTitle(st.id, e.target.value)}
            disabled={!canEdit}
            aria-label="Título da subtarefa"
            style={{
              flex: 1, fontSize: 14, color: st.checked ? theme.textMuted : theme.text,
              textDecoration: st.checked ? "line-through" : "none",
              background: "transparent", border: "none", outline: "none",
              fontFamily: "inherit", padding: 0,
            }}
          />
          <select
            value={st.status}
            onChange={(e) => updateStatus(st.id, e.target.value)}
            disabled={!canEdit}
            aria-label="Status da subtarefa"
            style={{
              background: theme.inputBg, border: `1px solid ${theme.inputBorder}`,
              borderRadius: 6, padding: "3px 8px", color: theme.text, fontSize: 11,
              outline: "none", cursor: canEdit ? "pointer" : "default",
              fontFamily: "inherit", colorScheme: theme.scheme,
            }}
          >
            {STATUS_OPTIONS.map((s) => <option key={s.value} value={s.value}>{s.label}</option>)}
          </select>
          {canEdit && (
            <button
              onClick={() => remove(st.id)}
              aria-label="Remover subtarefa"
              style={{ background: "none", border: "none", color: theme.textMuted, cursor: "pointer", fontSize: 16, padding: "0 4px", opacity: 0.4 }}
              onMouseEnter={(e) => (e.currentTarget.style.opacity = "1")}
              onMouseLeave={(e) => (e.currentTarget.style.opacity = "0.4")}
            >
              ×
            </button>
          )}
        </div>
      ))}

      {canEdit && (
        <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 0" }}>
          <div style={{ width: 18, height: 18, borderRadius: 4, border: `2px dashed ${theme.textMuted}`, opacity: 0.4, flexShrink: 0 }} />
          <input
            value={newTitle}
            onChange={(e) => setNewTitle(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") addSubtask(); }}
            placeholder="Adicionar subtarefa..."
            aria-label="Nova subtarefa"
            style={{ flex: 1, background: "transparent", border: "none", color: theme.text, fontSize: 14, outline: "none", fontFamily: "inherit", padding: 0 }}
          />
        </div>
      )}
    </div>
  );
}

