function formatBytes(n: number | null): string {
  if (!n) return "";
  if (n < 1024) return `${n} B`;
  if (n < 1048576) return `${Math.round(n / 1024)} KB`;
  return `${(n / 1048576).toFixed(1)} MB`;
}

function AttachmentsBlock({ taskId, theme }: { taskId: string; theme: Theme }) {
  const [items, setItems] = useState<TaskAttachment[]>([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);

  const load = useCallback(async () => {
    try { setItems(await api.getTaskAttachments(taskId)); } catch { /* noop */ } finally { setLoading(false); }
  }, [taskId]);
  useEffect(() => { load(); }, [load]);

  const onPick = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    if (file.size > 52428800) { alert("Arquivo acima de 50 MB."); return; }
    setUploading(true);
    try {
      const att = await api.uploadTaskAttachment(taskId, file);
      setItems((prev) => [...prev, att]);
    } catch (err) {
      alert(err instanceof Error ? err.message : "Falha ao enviar arquivo.");
    } finally {
      setUploading(false);
    }
  };

  const openAtt = async (id: string) => {
    try { const { url } = await api.getAttachmentUrl(id); window.open(url, "_blank", "noopener"); } catch { /* noop */ }
  };

  const removeAtt = async (id: string) => {
    if (!window.confirm("Remover este anexo?")) return;
    setItems((prev) => prev.filter((a) => a.id !== id));
    try { await api.deleteAttachment(id); } catch { load(); }
  };

  return (
    <div style={{ marginTop: 28 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
        <h3 style={{ fontSize: 14, fontWeight: 700, color: theme.text, display: "flex", alignItems: "center", gap: 7, margin: 0 }}>
          <Paperclip size={15} aria-hidden /> Anexos {items.length > 0 && <span style={{ fontSize: 12, color: theme.textMuted, fontWeight: 600 }}>({items.length})</span>}
        </h3>
        <button onClick={() => fileRef.current?.click()} disabled={uploading}
          style={{ display: "inline-flex", alignItems: "center", gap: 6, background: theme.inputBg, border: `1px solid ${theme.border}`, color: theme.text, borderRadius: 8, padding: "6px 12px", cursor: uploading ? "default" : "pointer", fontSize: 12, fontWeight: 600, fontFamily: "inherit", opacity: uploading ? 0.6 : 1 }}>
          <Plus size={13} aria-hidden /> {uploading ? "Enviando…" : "Anexar arquivo"}
        </button>
        <input ref={fileRef} type="file" onChange={onPick} style={{ display: "none" }} />
      </div>

      {loading ? (
        <div style={{ fontSize: 13, color: theme.textMuted }}>Carregando…</div>
      ) : items.length === 0 ? (
        <div style={{ fontSize: 13, color: theme.textMuted }}>Nenhum anexo. Arquivos até 50 MB.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          {items.map((a) => (
            <div key={a.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 12px", borderRadius: 8, border: `1px solid ${theme.border}`, background: theme.surface }}>
              <span style={{ color: "var(--primary)", flexShrink: 0 }}><Paperclip size={15} /></span>
              <button onClick={() => openAtt(a.id)} title="Abrir / baixar"
                style={{ flex: 1, minWidth: 0, textAlign: "left", background: "none", border: "none", cursor: "pointer", fontFamily: "inherit", padding: 0 }}>
                <span style={{ display: "block", fontSize: 13, color: theme.text, fontWeight: 500, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{a.fileName}</span>
                <span style={{ fontSize: 11, color: theme.textMuted }}>{formatBytes(a.sizeBytes)}{a.sizeBytes ? " · " : ""}{relTime(a.createdAt)}</span>
              </button>
              <button onClick={() => openAtt(a.id)} aria-label="Baixar" title="Baixar"
                style={{ background: "none", border: "none", color: theme.textSecondary, cursor: "pointer", display: "flex", padding: 4, borderRadius: 6, flexShrink: 0 }}>
                <Download size={15} />
              </button>
              <button onClick={() => removeAtt(a.id)} aria-label="Remover" title="Remover"
                style={{ background: "none", border: "none", color: theme.textMuted, cursor: "pointer", display: "flex", padding: 4, borderRadius: 6, flexShrink: 0 }}>
                <Trash2 size={15} />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function relTime(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime();
  const min = Math.floor(diff / 60000);
  if (min < 1) return "agora";
  if (min < 60) return `há ${min}min`;
  const h = Math.floor(min / 60);
  if (h < 24) return `há ${h}h`;
  const days = Math.floor(h / 24);
  if (days < 7) return `há ${days}d`;
  return new Date(iso).toLocaleDateString("pt-BR");
}

function TaskComments({ taskId, users, theme, canEdit }: { taskId: string; users: User[]; theme: Theme; canEdit: boolean }) {
  const [comments, setComments] = useState<TaskComment[]>([]);
  const [body, setBody] = useState("");
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    let active = true;
    api.getTaskComments(taskId)
      .then((c) => { if (active) setComments(c); })
      .catch(() => {})
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [taskId]);

  const submit = async () => {
    const text = body.trim();
    if (!text || submitting) return;
    setSubmitting(true);
    try {
      const c = await api.addTaskComment(taskId, text);
      setComments((prev) => [...prev, c]);
      setBody("");
    } catch { /* noop */ } finally { setSubmitting(false); }
  };

  return (
    <div style={{ marginTop: 28 }}>
      <div style={{ fontSize: 14, fontWeight: 600, color: theme.text, marginBottom: 12 }}>
        Comentários {comments.length > 0 && <span style={{ color: theme.textMuted, fontWeight: 500 }}>· {comments.length}</span>}
      </div>

      {loading ? (
        <div style={{ fontSize: 13, color: theme.textMuted, marginBottom: 12 }}>Carregando…</div>
      ) : comments.length === 0 ? (
        <div style={{ fontSize: 13, color: theme.textMuted, marginBottom: 12 }}>Nenhum comentário ainda.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 14, marginBottom: 16 }}>
          {comments.map((c) => {
            const author = users.find((u) => u.id === c.userId);
            return (
              <div key={c.id} style={{ display: "flex", gap: 10 }}>
                <UserAvatar avatar={author?.avatar || ""} name={author?.name || "?"} size={32} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                    <span style={{ fontSize: 13, fontWeight: 600, color: theme.text }}>{author?.name || "Usuário"}</span>
                    <span style={{ fontSize: 11, color: theme.textMuted }}>{relTime(c.createdAt)}</span>
                  </div>
                  <div style={{ fontSize: 14, color: theme.textSecondary, whiteSpace: "pre-wrap", wordBreak: "break-word", marginTop: 2 }}>{c.body}</div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {canEdit && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          <textarea
            value={body}
            onChange={(e) => setBody(e.target.value)}
            onKeyDown={(e) => { if ((e.metaKey || e.ctrlKey) && e.key === "Enter") submit(); }}
            placeholder="Escreva um comentário… (Cmd+Enter envia)"
            rows={2}
            style={{ width: "100%", resize: "vertical", background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 10, padding: "10px 12px", color: theme.text, fontSize: 14, outline: "none", fontFamily: "inherit" }}
          />
          <div style={{ display: "flex", justifyContent: "flex-end" }}>
            <button onClick={submit} disabled={!body.trim() || submitting}
              style={{ background: "var(--primary)", color: "#fff", border: "none", borderRadius: 8, padding: "8px 16px", fontSize: 13, fontWeight: 600, fontFamily: "inherit", cursor: body.trim() && !submitting ? "pointer" : "default", opacity: body.trim() && !submitting ? 1 : 0.5 }}>
              {submitting ? "Enviando…" : "Comentar"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}


// ——— Canais do Slack por grupo ———
function SlackChannels({ projects, workspaces, theme }: { projects: Project[]; workspaces: Workspace[]; theme: Theme }) {
  const inputStyle: CSSProperties = { width: "100%", padding: "8px 11px", background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 8, color: theme.text, fontSize: 13, outline: "none", fontFamily: "inherit" };
  const [config, setConfig] = useState<Record<string, { canalNome: string; configurado: boolean }>>({});
  const [rascunho, setRascunho] = useState<Record<string, string>>({});
  const [nomes, setNomes] = useState<Record<string, string>>({});
  const [msg, setMsg] = useState<string | null>(null);
  const [salvando, setSalvando] = useState<string | null>(null);

  useEffect(() => {
    slackApi.list()
      .then((rows) => {
        const map: Record<string, { canalNome: string; configurado: boolean }> = {};
        const nomeMap: Record<string, string> = {};
        rows.forEach((r) => { map[r.projectId] = { canalNome: r.canalNome, configurado: r.configurado }; nomeMap[r.projectId] = r.canalNome; });
        setConfig(map);
        setNomes(nomeMap);
      })
      .catch(() => setMsg("Não foi possível carregar os canais"));
  }, []);

  const salvar = async (projectId: string) => {
    setSalvando(projectId);
    try {
      const url = (rascunho[projectId] ?? "").trim();
      const r = await slackApi.save(projectId, url, nomes[projectId]);
      setConfig((prev) => ({ ...prev, [projectId]: { canalNome: nomes[projectId] ?? "", configurado: r.configurado } }));
      setRascunho((prev) => ({ ...prev, [projectId]: "" }));
      setMsg(r.configurado ? "Canal salvo" : "Canal removido");
    } catch (err) {
      setMsg(err instanceof Error ? err.message : "Falha ao salvar");
    }
    setSalvando(null);
  };

  const visiveis = projects.filter((p) => !p.id.startsWith("personal-"));

  return (
    <div>
      <div style={{ fontSize: 12, color: theme.textMuted, marginBottom: 16, lineHeight: 1.6 }}>
        Cada grupo avisa no seu canal quando uma tarefa é criada — manualmente ou por outro sistema, como o de copy.
        Pegue a URL em <strong>Slack → Apps → Incoming Webhooks → Add to Slack</strong>, escolhendo o canal.
        A URL fica só no servidor e não volta pra esta tela depois de salva.
      </div>
      {msg && (
        <div style={{ fontSize: 12, color: "var(--primary)", background: "var(--primary-soft)", padding: "8px 12px", borderRadius: 8, marginBottom: 14 }}>{msg}</div>
      )}
      {visiveis.map((p) => {
        const ws = workspaces.find((w) => w.id === p.workspaceId);
        const atual = config[p.id];
        return (
          <div key={p.id} style={{ display: "grid", gridTemplateColumns: "minmax(140px, 1fr) 2fr 150px auto", gap: 10, alignItems: "center", padding: "10px 0", borderBottom: `1px solid ${theme.border}` }}>
            <div style={{ minWidth: 0 }}>
              <div style={{ fontSize: 13, fontWeight: 600, color: theme.text, display: "flex", alignItems: "center", gap: 7 }}>
                <span style={{ width: 8, height: 8, borderRadius: "50%", background: p.color, flexShrink: 0 }} />
                <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{p.name}</span>
              </div>
              <div style={{ fontSize: 10, color: theme.textMuted, marginTop: 2 }}>{ws?.name ?? "sem workspace"}</div>
            </div>
            <input
              value={rascunho[p.id] ?? ""}
              onChange={(e) => setRascunho((prev) => ({ ...prev, [p.id]: e.target.value }))}
              placeholder={atual?.configurado ? "•••• configurado — cole outra URL para trocar" : "https://hooks.slack.com/services/..."}
              style={{ ...inputStyle, width: "100%", fontSize: 12 }} />
            <input
              value={nomes[p.id] ?? ""}
              onChange={(e) => setNomes((prev) => ({ ...prev, [p.id]: e.target.value }))}
              placeholder="#canal (opcional)"
              style={{ ...inputStyle, width: "100%", fontSize: 12 }} />
            <button onClick={() => salvar(p.id)} disabled={salvando === p.id}
              style={{ background: "var(--primary)", border: "none", color: "#fff", borderRadius: 8, padding: "8px 14px", cursor: "pointer", fontSize: 12, fontWeight: 700, fontFamily: "inherit", whiteSpace: "nowrap", opacity: salvando === p.id ? 0.6 : 1 }}>
              {atual?.configurado && !(rascunho[p.id] ?? "").trim() ? "Remover" : "Salvar"}
            </button>
          </div>
        );
      })}
    </div>
  );
}

// ——— Task Row ———
interface TaskRowProps {
  task: Task;
  projects: Project[];
  users: User[];
  tags: Tag[];
  onUpdate: (task: Task) => void;
  onOpen: (task: Task) => void;
  isSubtask?: boolean;
  theme: Theme;
  canEdit: boolean;
  isExpanded?: boolean;
  onToggleExpand?: (id: string) => void;
  onDelete?: (task: Task) => void;
  /** Quando presente, a coluna "Projeto" vira "Grupo" (visão de um projeto só). */
  groupOptions?: { id: string; name: string; color: string }[];
}

function TaskRow({ task, projects, users, tags, onUpdate, onOpen, isSubtask, theme, canEdit, isExpanded, onToggleExpand, onDelete, groupOptions }: TaskRowProps) {
  const overdue = task.deadline && new Date(task.deadline) < new Date() && task.status !== "done";
  const stDone = (task.subtasks || []).filter((s) => s.checked).length;
  const stTotal = (task.subtasks || []).length;
  const assignee = users?.find((u) => u.id === task.assignedTo);

  return (
    <div onClick={() => onOpen(task)} className="task-row"
      style={{
        display: "grid",
        gridTemplateColumns: isSubtask ? GRID_COLUMNS_SUBTASK : GRID_COLUMNS,
        alignItems: "center", padding: isSubtask ? "6px 14px 6px 40px" : "10px 14px", gap: 8,
        borderBottom: `1px solid ${theme.border}`, cursor: "pointer", fontSize: 14,
        borderLeft: isSubtask ? undefined : `4px solid ${priorityColor(task.priority)}`,
        background: isSubtask
          ? theme.surfaceHover
          : (task.priority === "high" || task.priority === "critical") ? "rgba(226,68,92,0.05)" : "transparent",
        transition: "background 0.15s"
      }}>
      <button onClick={(e) => { e.stopPropagation(); if (canEdit) onUpdate({ ...task, checked: !task.checked }); }}
        style={{ width: 20, height: 20, borderRadius: 6, border: `2px solid ${task.checked ? "#00C875" : theme.inputBorder}`, background: task.checked ? "#00C875" : "transparent", cursor: canEdit ? "pointer" : "default", display: "flex", alignItems: "center", justifyContent: "center", padding: 0 }}>
        {task.checked && <span style={{ color: "#fff", fontSize: 12, fontWeight: 700 }}>✓</span>}
      </button>

      <div style={{ display: "flex", alignItems: "center", gap: 8, minWidth: 0 }}>
        {!isSubtask && stTotal > 0 && (
          <button onClick={(e) => { e.stopPropagation(); onToggleExpand?.(task.id); }}
            style={{ background: "none", border: "none", cursor: "pointer", color: theme.textSecondary, fontSize: 10, padding: "2px 4px", borderRadius: 4, transition: "transform 0.2s", transform: isExpanded ? "rotate(90deg)" : "rotate(0deg)", flexShrink: 0 }}>
            ▶
          </button>
        )}
        <span style={{ color: task.checked ? theme.textMuted : theme.text, fontWeight: 500, textDecoration: task.checked ? "line-through" : "none", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
          {isSubtask && <span style={{ color: theme.textMuted, marginRight: 6 }}>↳</span>}
          {task.title}
        </span>
        {stTotal > 0 && !isSubtask && <span style={{ fontSize: 11, color: theme.textSecondary, background: theme.inputBg, padding: "2px 7px", borderRadius: 10, whiteSpace: "nowrap", flexShrink: 0 }}>{stDone}/{stTotal}</span>}
        {task.link && <a href={task.link} target="_blank" rel="noopener noreferrer" onClick={(e) => e.stopPropagation()} style={{ color: "#579BFC", fontSize: 12, flexShrink: 0 }}>🔗</a>}
      </div>

      <div onClick={(e) => e.stopPropagation()}>
        <StatusBadge value={task.status} onChange={(v: string) => onUpdate({ ...task, status: v })} compact={isSubtask} theme={theme} disabled={!canEdit} />
      </div>

      {!isSubtask && (
        <div onClick={(e) => e.stopPropagation()}>
          {groupOptions ? (
            <Dropdown
              options={[{ value: "", label: "Sem grupo", color: theme.textMuted, name: "Sem grupo" }, ...groupOptions.map((g) => ({ value: g.id, label: g.name, color: g.color, name: g.name }))]}
              value={task.groupId || ""}
              onChange={(v: string) => onUpdate({ ...task, groupId: v || null })}
              theme={theme}
              disabled={!canEdit}
              renderOption={(o) => <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 13, color: o.color || theme.textSecondary }}><span style={{ width: 8, height: 8, borderRadius: "50%", background: o.color || theme.textMuted, flexShrink: 0 }} />{o.label || o.name}</span>} />
          ) : (
            <Dropdown options={projects.map((p) => ({ value: p.id, label: p.name, color: p.color, icon: p.icon, name: p.name }))} value={task.projectId} onChange={(v: string) => onUpdate({ ...task, projectId: v })} theme={theme} disabled={!canEdit}
              renderOption={(o) => <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 13, color: o.color || theme.textSecondary }}><span style={{ width: 8, height: 8, borderRadius: "50%", background: o.color || theme.textMuted, flexShrink: 0 }} />{o.label || o.name}</span>} />
          )}
        </div>
      )}

      <div onClick={(e) => e.stopPropagation()}>
        <input type="date" value={task.deadline || ""} readOnly={!canEdit} onChange={(e) => canEdit && onUpdate({ ...task, deadline: e.target.value })}
          style={{ background: "transparent", border: "none", color: overdue ? "#E2445C" : theme.textSecondary, fontSize: 13, outline: "none", width: "100%", colorScheme: theme.scheme, cursor: canEdit ? "pointer" : "default", fontFamily: "inherit" }} />
      </div>

      {!isSubtask && (
        <div onClick={(e) => e.stopPropagation()}>
          <PriorityBadge value={task.priority} onChange={(v: string) => onUpdate({ ...task, priority: v })} theme={theme} disabled={!canEdit} />
        </div>
      )}

      {!isSubtask && (
        <div onClick={(e) => e.stopPropagation()}>
          <Dropdown
            options={[{ value: "", label: "Ninguém", avatar: "—" }, ...(users || []).map((u) => ({ value: u.id, label: u.name, avatar: u.avatar }))]}
            value={task.assignedTo || ""}
            onChange={(v: string) => canEdit && onUpdate({ ...task, assignedTo: v || null })}
            theme={theme}
            disabled={!canEdit}
            renderOption={(o, isSelected) => (
              <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 13, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                <span style={{ flexShrink: 0 }}>{o.avatar}</span>
                <span style={{ overflow: "hidden", textOverflow: "ellipsis" }}>{isSelected ? (o.label === "Ninguém" ? "—" : o.label) : o.label}</span>
              </span>
            )}
          />
        </div>
      )}

      {!isSubtask && (
        <div onClick={(e) => e.stopPropagation()}>
          <TagsPicker
            allTags={tags}
            selectedIds={task.tagIds || []}
            onChange={(ids) => onUpdate({ ...task, tagIds: ids })}
            disabled={!canEdit}
            variant="compact"
          />
        </div>
      )}

      {!isSubtask && (
        <LinkCell task={task} theme={theme} canEdit={canEdit} onUpdate={onUpdate} />
      )}

      <div style={{ display: "flex", gap: 4, justifyContent: "flex-end", alignItems: "center" }}>
        {canEdit && onDelete && !isSubtask && (
          <button onClick={(e) => { e.stopPropagation(); onDelete(task); }}
            className="task-delete-btn"
            aria-label={`Excluir tarefa ${task.title}`}
            title="Excluir tarefa"
            style={{ background: "none", border: "none", color: "#E2445C", borderRadius: 6, padding: "4px 6px", cursor: "pointer", fontSize: 13, opacity: 0.35, transition: "opacity 0.15s", lineHeight: 1 }}>
            <Trash2 size={15} aria-hidden />
          </button>
        )}
        <button onClick={(e) => { e.stopPropagation(); onOpen(task); }}
          style={{ background: theme.inputBg, border: "none", color: theme.textSecondary, borderRadius: 6, padding: "4px 8px", cursor: "pointer", fontSize: 14 }}>❯</button>
      </div>
    </div>
  );
}

// ——— Card de tarefa no mobile (empilhado, alvos ≥44px) ———
function MobileTaskCard({ task, projects, users, onUpdate, onOpen, theme, canEdit }: {
  task: Task; projects: Project[]; users: User[]; onUpdate: (t: Task) => void; onOpen: (t: Task) => void; theme: Theme; canEdit: boolean;
}) {
  const overdue = task.deadline && new Date(task.deadline) < new Date() && task.status !== "done";
  const stDone = (task.subtasks || []).filter((s) => s.checked).length;
  const stTotal = (task.subtasks || []).length;
  const assignee = users?.find((u) => u.id === task.assignedTo);
  const project = projects.find((p) => p.id === task.projectId);
  const isHigh = task.priority === "high" || task.priority === "critical";

  return (
    <div onClick={() => onOpen(task)} className="task-row mobile-task-card"
      style={{
        display: "flex", flexDirection: "column", gap: 8,
        padding: "12px 14px", borderBottom: `1px solid ${theme.border}`,
        borderLeft: `4px solid ${priorityColor(task.priority)}`,
        background: isHigh ? "rgba(226,68,92,0.05)" : "transparent",
        cursor: "pointer",
      }}>
      {/* Linha 1: check + título + chevron */}
      <div style={{ display: "flex", alignItems: "flex-start", gap: 10 }}>
        <button onClick={(e) => { e.stopPropagation(); if (canEdit) onUpdate({ ...task, checked: !task.checked }); }}
          aria-label={task.checked ? "Desmarcar" : "Concluir"}
          style={{ width: 26, height: 26, borderRadius: 7, border: `2px solid ${task.checked ? "#00C875" : theme.inputBorder}`, background: task.checked ? "#00C875" : "transparent", cursor: canEdit ? "pointer" : "default", display: "flex", alignItems: "center", justifyContent: "center", padding: 0, flexShrink: 0, marginTop: 1 }}>
          {task.checked && <span style={{ color: "#fff", fontSize: 14, fontWeight: 700 }}>✓</span>}
        </button>
        <span style={{ flex: 1, minWidth: 0, color: task.checked ? theme.textMuted : theme.text, fontWeight: 600, fontSize: 15, lineHeight: 1.35, textDecoration: task.checked ? "line-through" : "none" }}>
          {task.title}
        </span>
        <span aria-hidden style={{ color: theme.textMuted, fontSize: 16, flexShrink: 0, lineHeight: 1.5 }}>❯</span>
      </div>

      {/* Linha 2: status (interativo) + meta */}
      <div style={{ display: "flex", alignItems: "center", flexWrap: "wrap", gap: 8, paddingLeft: 36 }}>
        <div onClick={(e) => e.stopPropagation()}>
          <StatusBadge value={task.status} onChange={(v: string) => onUpdate({ ...task, status: v })} theme={theme} disabled={!canEdit} />
        </div>
        {project && (
          <span style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 12, color: project.color || theme.textSecondary, fontWeight: 600, maxWidth: 140, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            <span style={{ width: 9, height: 9, borderRadius: "50%", background: project.color, flexShrink: 0 }} />{project.name}
          </span>
        )}
        {task.deadline && (
          <span style={{ fontSize: 12, fontWeight: 600, color: overdue ? "#E2445C" : theme.textSecondary }}>
            {new Date(task.deadline + "T00:00:00").toLocaleDateString("pt-BR", { day: "2-digit", month: "short" })}
          </span>
        )}
        {stTotal > 0 && (
          <span style={{ fontSize: 11, color: theme.textSecondary, background: theme.inputBg, padding: "2px 7px", borderRadius: 10 }}>{stDone}/{stTotal}</span>
        )}
        {assignee && (
          <span style={{ marginLeft: "auto" }}>
            <UserAvatar avatar={assignee.avatar} name={assignee.name} size={24} background="var(--primary-soft)" />
          </span>
        )}
      </div>
    </div>
  );
}

// ——— Link Cell ———
function LinkCell({ task, theme, canEdit, onUpdate }: { task: Task; theme: Theme; canEdit: boolean; onUpdate: (t: Task) => void }) {
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState(task.link || "");
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { setValue(task.link || ""); }, [task.link]);
  useEffect(() => { if (editing) inputRef.current?.focus(); }, [editing]);

  const save = () => {
    // Colar "www.figma.com/..." sem protocolo era rejeitado pela API (Invalid URL).
    const raw = value.trim();
    const v = raw && !/^https?:\/\//i.test(raw) ? `https://${raw}` : raw;
    if (v !== value) setValue(v);
    if (v !== (task.link || "")) onUpdate({ ...task, link: v });
    setEditing(false);
  };

  const isValid = (() => {
    if (!task.link) return false;
    try { new URL(task.link); return true; } catch { return false; }
  })();

  if (editing) {
    return (
      <div onClick={(e) => e.stopPropagation()}>
        <input
          ref={inputRef}
          value={value}
          onChange={(e) => setValue(e.target.value)}
          onBlur={save}
          onKeyDown={(e) => {
            if (e.key === "Enter") save();
            if (e.key === "Escape") { setValue(task.link || ""); setEditing(false); }
          }}
          placeholder="https://…"
          aria-label="URL do link"
          style={{
            width: "100%", background: theme.inputBg, border: `1px solid ${theme.inputBorder}`,
            borderRadius: 6, padding: "4px 8px", color: theme.text, fontSize: 12,
            outline: "none", fontFamily: "inherit",
          }}
        />
      </div>
    );
  }

  if (isValid) {
    return (
      <div style={{ display: "flex", alignItems: "center", gap: 4 }} onClick={(e) => e.stopPropagation()}>
        <a
          href={task.link}
          target="_blank"
          rel="noopener noreferrer"
          title={task.link}
          aria-label={`Abrir ${task.link}`}
          style={{ color: "var(--primary)", display: "inline-flex", alignItems: "center", gap: 4, fontSize: 12, textDecoration: "none", padding: "2px 6px", borderRadius: 6, background: "var(--primary-soft)" }}
        >
          <Link2 size={14} aria-hidden /> abrir
        </a>
        {canEdit && (
          <button
            onClick={() => setEditing(true)}
            aria-label="Editar link"
            title="Editar"
            style={{ background: "transparent", border: "none", color: theme.textMuted, cursor: "pointer", padding: "2px 4px", borderRadius: 4, fontSize: 11, opacity: 0.5 }}
          >
            ✎
          </button>
        )}
      </div>
    );
  }

  if (!canEdit) return <div />;

  return (
    <button
      onClick={(e) => { e.stopPropagation(); setEditing(true); }}
      aria-label="Adicionar link"
      style={{ background: "transparent", border: `1px dashed ${theme.border}`, color: theme.textMuted, cursor: "pointer", padding: "4px 8px", borderRadius: 6, fontSize: 11, display: "inline-flex", alignItems: "center", gap: 4, fontFamily: "inherit" }}
    >
      <Link2 size={12} aria-hidden /> link
    </button>
  );
}

// ——— Group Header ———
function GroupHeader({ group, collapsed, onToggle, taskCount, theme, dragHandleProps, canEdit, onQuickAdd, onRename, onDelete }: {
  group: Group;
  collapsed: boolean;
  onToggle: () => void;
  taskCount: number;
  theme: Theme;
  dragHandleProps?: Record<string, unknown>;
  canEdit?: boolean;
  onQuickAdd?: () => void;
  onRename?: (name: string) => void;
  onDelete?: () => void;
}) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(group.name);
  const editable = !!onRename && !!canEdit;

  const commit = () => {
    setEditing(false);
    const name = draft.trim();
    if (name && name !== group.name) onRename?.(name);
    else setDraft(group.name);
  };

  return (
    <div onClick={onToggle} style={{
      display: "flex", alignItems: "center", gap: 10, padding: "10px 12px",
      borderLeft: `4px solid ${group.color}`, background: theme.surfaceHover,
      cursor: "pointer", userSelect: "none", borderBottom: `1px solid ${theme.border}`,
      borderRadius: "12px 12px 0 0"
    }}>
      {dragHandleProps && (
        <span {...dragHandleProps} onClick={(e) => e.stopPropagation()} style={{ cursor: "grab", fontSize: 14, color: theme.textMuted, padding: "2px 4px", display: "flex", alignItems: "center", opacity: 0.5 }} title="Arrastar grupo">
          ⠿
        </span>
      )}
      <span style={{ fontSize: 10, color: group.color, transition: "transform 0.2s", transform: collapsed ? "rotate(0deg)" : "rotate(90deg)", fontWeight: 700 }}>▶</span>
      <span style={{ width: 10, height: 10, borderRadius: "50%", background: group.color, flexShrink: 0 }} />
      {editing ? (
        <input
          autoFocus value={draft}
          onClick={(e) => e.stopPropagation()}
          onChange={(e) => setDraft(e.target.value)}
          onBlur={commit}
          onKeyDown={(e) => {
            e.stopPropagation();
            if (e.key === "Enter") commit();
            if (e.key === "Escape") { setDraft(group.name); setEditing(false); }
          }}
          style={{ fontSize: 15, fontWeight: 700, color: group.color, background: theme.inputBg, border: `1px solid ${theme.border}`, borderRadius: 6, padding: "2px 8px", outline: "none", fontFamily: "inherit" }}
        />
      ) : (
        <span
          onDoubleClick={(e) => { if (editable) { e.stopPropagation(); setDraft(group.name); setEditing(true); } }}
          title={editable ? "Clique duas vezes para renomear" : undefined}
          style={{ fontSize: 15, fontWeight: 700, color: group.color }}
        >{group.name}</span>
      )}
      <span style={{ fontSize: 12, color: theme.textMuted, background: theme.inputBg, padding: "2px 8px", borderRadius: 10 }}>{taskCount}</span>

      {canEdit && onQuickAdd && (
        <button
          onClick={(e) => { e.stopPropagation(); onQuickAdd(); }}
          aria-label={`Nova tarefa em ${group.name}`}
          title="Nova tarefa neste grupo"
          style={{
            marginLeft: "auto",
            display: "inline-flex", alignItems: "center", gap: 4,
            background: theme.inputBg, border: `1px solid ${theme.border}`, color: group.color,
            padding: "4px 10px", borderRadius: 8, cursor: "pointer", fontSize: 12, fontWeight: 600,
            fontFamily: "inherit",
          }}
        >
          + tarefa
        </button>
      )}

      {canEdit && onDelete && (
        <button
          onClick={(e) => { e.stopPropagation(); onDelete(); }}
          aria-label={`Excluir grupo ${group.name}`}
          title="Excluir grupo"
          style={{
            marginLeft: onQuickAdd ? 0 : "auto",
            background: "transparent", border: `1px solid ${theme.border}`, color: theme.textMuted,
            padding: "4px 9px", borderRadius: 8, cursor: "pointer", fontSize: 12, fontFamily: "inherit",
          }}
        >
          ✕
        </button>
      )}
    </div>
  );
}

// ——— Sortable Group Wrapper ———
function SortableGroup({ id, children }: { id: string; children: (dragHandleProps: Record<string, unknown>) => ReactNode }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id });
  const style: CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
    position: "relative",
    zIndex: isDragging ? 10 : "auto",
  };
  return (
    <div ref={setNodeRef} style={style}>
      {children({ ...attributes, ...listeners })}
    </div>
  );
}

// ——— Inline Add Row ———
function InlineAddRow({ groupProjectId, groupId, theme, onAdd }: { groupProjectId: string; groupId?: string | null; theme: Theme; onAdd: (title: string, projectId: string, groupId: string | null) => void }) {
  const [active, setActive] = useState(false);
  const [value, setValue] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (active && inputRef.current) inputRef.current.focus();
  }, [active]);

  const submit = () => {
    if (value.trim()) {
      onAdd(value.trim(), groupProjectId, groupId ?? null);
      setValue("");
      setActive(false);
    }
  };

  if (!active) {
    return (
      <div onClick={() => setActive(true)} style={{
        display: "grid", gridTemplateColumns: GRID_COLUMNS, padding: "8px 14px", gap: 8,
        cursor: "pointer", borderBottom: `1px solid ${theme.border}`, opacity: 0.5,
        transition: "opacity 0.15s", fontSize: 14, color: theme.textMuted
      }}
        onMouseEnter={(e) => (e.currentTarget.style.opacity = "0.8")}
        onMouseLeave={(e) => (e.currentTarget.style.opacity = "0.5")}>
        <div></div>
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <span style={{ fontSize: 14 }}>+</span> Adicionar tarefa
        </div>
      </div>
    );
  }

  return (
    <div style={{
      display: "grid", gridTemplateColumns: GRID_COLUMNS, padding: "8px 14px", gap: 8,
      borderBottom: `1px solid ${theme.border}`, background: theme.surfaceHover
    }}>
      <div></div>
      <div>
        <input ref={inputRef} value={value} onChange={(e) => setValue(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") submit(); if (e.key === "Escape") { setValue(""); setActive(false); } }}
          onBlur={() => { if (!value.trim()) setActive(false); }}
          placeholder="Nome da tarefa..."
          style={{
            width: "100%", background: theme.inputBg, border: `1px solid ${theme.inputBorder}`,
            borderRadius: 6, padding: "6px 10px", color: theme.text, fontSize: 13,
            outline: "none", fontFamily: "inherit"
          }} />
      </div>
    </div>
  );
}

// ——— Personal Area Components ———

function StatCard({ label, value, color, theme }: { label: string; value: number; color: string; theme: Theme }) {
  return (
    <div style={{ padding: "12px 16px", borderRadius: 12, background: theme.badgeBg(color), border: `1px solid ${theme.badgeBorder(color)}`, minWidth: 100, textAlign: "center", flex: 1 }}>
      <div style={{ fontSize: 24, fontWeight: 800, color }}>{value}</div>
      <div style={{ fontSize: 11, color: theme.textSecondary, fontWeight: 600, marginTop: 2 }}>{label}</div>
    </div>
  );
}

interface MyTasksTabProps {
  theme: Theme;
  currentUser: User;
  tasks: Task[];
  projects: Project[];
  users: User[];
  tags: Tag[];
  canEdit: boolean;
  onOpenTask: (task: Task) => void;
  onUpdateTask: (task: Task) => void;
  onReload?: () => Promise<void> | void;
}

function MyTasksTab({ theme, currentUser, tasks, projects, users, tags, canEdit, onOpenTask, onUpdateTask, onReload }: MyTasksTabProps) {
  const myTasks = tasks.filter((t) => t.assignedTo === currentUser.id);
  const [myCollapsed, setMyCollapsed] = useState<Set<string>>(new Set());
  const [myExpanded, setMyExpanded] = useState<Set<string>>(new Set());
  const [draft, setDraft] = useState("");
  const [adding, setAdding] = useState(false);

  const addQuick = async () => {
    const title = draft.trim();
    if (!title || adding) return;
    setAdding(true);
    try {
      await api.addPersonalTask({ title });
      setDraft("");
      await onReload?.();
    } catch { /* mantém o texto pra tentar de novo */ }
    finally { setAdding(false); }
  };

  const myGroups: Group[] = useMemo(() => {
    const map = new Map<string, Group>();
    myTasks.forEach((t) => {
      const proj = projects.find((p) => p.id === t.projectId);
      if (!proj) return;
      if (!map.has(proj.id)) map.set(proj.id, { id: proj.id, name: proj.name, color: proj.color, icon: proj.icon, tasks: [], projectId: proj.id, kind: "project" });
      map.get(proj.id)!.tasks.push(t);
    });
    return Array.from(map.values());
  }, [myTasks, projects]);

  const done = myTasks.filter((t) => t.status === "done").length;
  const overdue = myTasks.filter((t) => t.deadline && new Date(t.deadline) < new Date() && t.status !== "done").length;
  const doing = myTasks.filter((t) => t.status === "doing").length;

  return (
    <div>
      <div style={{ padding: "16px 24px", display: "flex", gap: 12, flexWrap: "wrap" }}>
        <StatCard label="Total" value={myTasks.length} color="var(--primary)" theme={theme} />
        <StatCard label="Concluídas" value={done} color="#00C875" theme={theme} />
        <StatCard label="Em progresso" value={doing} color="#FDAB3D" theme={theme} />
        <StatCard label="Atrasadas" value={overdue} color="#E2445C" theme={theme} />
      </div>
      <div style={{ padding: "0 24px 12px", display: "flex", gap: 8 }}>
        <input
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") addQuick(); }}
          placeholder="Escreva uma tarefa e Enter para criar…"
          aria-label="Nova tarefa pessoal"
          style={{ flex: 1, minWidth: 0, padding: "11px 14px", borderRadius: 10, border: `1px solid ${theme.inputBorder}`, background: theme.inputBg, color: theme.text, fontSize: 14, fontFamily: "inherit", outline: "none" }}
        />
        <button onClick={addQuick} disabled={!draft.trim() || adding}
          style={{ display: "inline-flex", alignItems: "center", gap: 6, flexShrink: 0, background: "var(--primary)", color: "#fff", border: "none", borderRadius: 10, padding: "0 18px", fontSize: 14, fontWeight: 700, cursor: draft.trim() && !adding ? "pointer" : "default", opacity: draft.trim() && !adding ? 1 : 0.5, fontFamily: "inherit" }}>
          <Plus size={16} aria-hidden /> {adding ? "Criando…" : "Adicionar"}
        </button>
      </div>
      <div style={{ padding: "0 24px 24px" }}>
      {myTasks.length === 0 && (
        <EmptyState
          icon={Inbox}
          title="Nenhuma tarefa por aqui ainda"
          description="Crie uma tarefa no campo acima, ou espere alguém te marcar numa tarefa de projeto."
        />
      )}
      {myGroups.map((group) => (
        <div key={group.id} style={{ marginBottom: 20, borderRadius: 12, border: `1px solid ${theme.border}`, overflow: "hidden", background: theme.surface }}>
          <GroupHeader group={group} collapsed={myCollapsed.has(group.id)} onToggle={() => setMyCollapsed((prev) => { const n = new Set(prev); n.has(group.id) ? n.delete(group.id) : n.add(group.id); return n; })} taskCount={group.tasks.length} theme={theme} />
          {!myCollapsed.has(group.id) && (<>
            <div style={{ display: "grid", gridTemplateColumns: GRID_COLUMNS, padding: "10px 14px", gap: 8, borderBottom: `1px solid ${theme.borderStrong}`, fontSize: 11, fontWeight: 700, color: theme.textMuted, textTransform: "uppercase", letterSpacing: 1.2, background: theme.surfaceHover, borderLeft: `4px solid ${group.color}` }}>
              <div></div><div>Tarefa</div><div>Status</div><div>Projeto</div><div>Prazo</div><div>Prioridade</div><div>Pessoa</div><div>Tags</div><div>Link</div><div></div>
            </div>
            {group.tasks.map((task) => (
              <div key={task.id} style={{ borderLeft: `4px solid ${group.color}` }}>
                <TaskRow task={task} projects={projects} users={users} tags={tags} onUpdate={onUpdateTask} onOpen={onOpenTask} theme={theme} canEdit={canEdit} isExpanded={myExpanded.has(task.id)} onToggleExpand={(id: string) => setMyExpanded((prev) => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; })} />
              </div>
            ))}
          </>)}
        </div>
      ))}
      </div>
    </div>
  );
}

function RichTextToolbar({ theme }: { theme: Theme }) {
  const exec = (cmd: string, val?: string) => { document.execCommand(cmd, false, val); };
  const insertLink = () => { const url = prompt("URL do link:"); if (url) exec("createLink", url); };
  const btns = [
    { label: "B", cmd: "bold", s: { fontWeight: 700 } as React.CSSProperties },
    { label: "I", cmd: "italic", s: { fontStyle: "italic" } as React.CSSProperties },
    { label: "U", cmd: "underline", s: { textDecoration: "underline" } as React.CSSProperties },
    { label: "• Lista", cmd: "insertUnorderedList", s: {} as React.CSSProperties },
    { label: "1. Lista", cmd: "insertOrderedList", s: {} as React.CSSProperties },
    { label: "🔗 Link", cmd: "link", s: {} as React.CSSProperties },
  ];
  return (
    <div style={{ padding: "8px 24px", borderBottom: `1px solid ${theme.border}`, display: "flex", gap: 4, flexWrap: "wrap" }}>
      {btns.map((b) => (
        <button key={b.cmd} onMouseDown={(e) => { e.preventDefault(); b.cmd === "link" ? insertLink() : exec(b.cmd); }}
          style={{ padding: "6px 12px", borderRadius: 6, border: `1px solid ${theme.border}`, background: theme.inputBg, color: theme.text, cursor: "pointer", fontSize: 12, fontFamily: "inherit", ...b.s }}>
          {b.label}
        </button>
      ))}
    </div>
  );
}

function NotesTab({ theme }: { theme: Theme; currentUser: User }) {
  const [notes, setNotes] = useState<Note[]>([]);
  const [selectedNote, setSelectedNote] = useState<Note | null>(null);
  const [searchNotes, setSearchNotes] = useState("");
  const [loading, setLoading] = useState(true);
  const saveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);
  const isDirtyRef = useRef(false);

  useEffect(() => { loadNotes(); return () => { if (saveTimerRef.current) clearTimeout(saveTimerRef.current); }; }, []);

  const loadNotes = async () => { setLoading(true); try { const data = await api.getNotes(); setNotes(data); } catch {} finally { setLoading(false); } };

  const createNote = async () => {
    try {
      const n = await api.createNote({ title: "Nova nota", content: "" });
      setNotes((prev) => [n, ...prev]);
      setSelectedNote(n);
    } catch {}
  };

  const saveNote = async (note: Note | null) => {
    if (!note || !isDirtyRef.current) return;
    isDirtyRef.current = false;
    try {
      const updated = await api.updateNote(note.id, { title: note.title, content: note.content, pinned: note.pinned });
      setNotes((prev) => prev.map((n) => (n.id === updated.id ? updated : n)));
    } catch {}
  };

  const scheduleAutosave = (note: Note) => {
    isDirtyRef.current = true;
    if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    saveTimerRef.current = setTimeout(() => saveNote(note), 1500);
  };

  const deleteNote = async (id: string) => {
    try { await api.deleteNote(id); setNotes((prev) => prev.filter((n) => n.id !== id)); } catch {}
  };

  const togglePin = async (note: Note) => {
    const newPinned = !note.pinned;
    try {
      const updated = await api.updateNote(note.id, { pinned: newPinned });
      setNotes((prev) => prev.map((n) => (n.id === updated.id ? updated : n)));
      if (selectedNote?.id === note.id) setSelectedNote({ ...selectedNote, pinned: newPinned });
    } catch {}
  };

  const filteredNotes = notes.filter((n) => !searchNotes || n.title.toLowerCase().includes(searchNotes.toLowerCase()) || (n.content || "").replace(/<[^>]*>/g, "").toLowerCase().includes(searchNotes.toLowerCase()));

  if (selectedNote) {
    return (
      <div style={{ display: "flex", flexDirection: "column", flex: 1, height: "100%" }}>
        <div style={{ padding: "16px 24px", borderBottom: `1px solid ${theme.border}`, display: "flex", alignItems: "center", gap: 12 }}>
          <button onClick={() => { saveNote(selectedNote); setSelectedNote(null); }}
            style={{ background: theme.inputBg, border: `1px solid ${theme.border}`, borderRadius: 8, padding: "6px 14px", color: theme.text, cursor: "pointer", fontSize: 13, fontFamily: "inherit" }}>← Voltar</button>
          <input value={selectedNote.title} onChange={(e) => { const u = { ...selectedNote, title: e.target.value }; setSelectedNote(u); scheduleAutosave(u); }}
            style={{ flex: 1, fontSize: 20, fontWeight: 700, background: "transparent", border: "none", color: theme.text, outline: "none", fontFamily: "inherit" }} />
          <button onMouseDown={(e) => { e.preventDefault(); togglePin(selectedNote); }}
            style={{ background: "none", border: "none", cursor: "pointer", fontSize: 18, opacity: selectedNote.pinned ? 1 : 0.4 }}>📌</button>
          <button onClick={() => { deleteNote(selectedNote.id); setSelectedNote(null); }}
            style={{ background: "none", border: "none", cursor: "pointer", fontSize: 16, color: "#E2445C" }}>🗑️</button>
        </div>
        <RichTextToolbar theme={theme} />
        <div ref={editorRef} contentEditable suppressContentEditableWarning
          onInput={() => { if (editorRef.current) { const u = { ...selectedNote, content: editorRef.current.innerHTML }; setSelectedNote(u); scheduleAutosave(u); } }}
          dangerouslySetInnerHTML={{ __html: selectedNote.content }}
          style={{ padding: "20px 24px", flex: 1, outline: "none", color: theme.text, fontSize: 14, lineHeight: 1.8, fontFamily: "inherit", overflowY: "auto", minHeight: 200 }}
        />
      </div>
    );
  }

  return (
    <div>
      <div style={{ padding: "16px 24px", display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
        <div style={{ position: "relative", flex: 1, minWidth: 180 }}>
          <span aria-hidden style={{ position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)", color: theme.textMuted, display: "flex" }}><Search size={16} /></span>
          <input value={searchNotes} onChange={(e) => setSearchNotes(e.target.value)} placeholder="Buscar anotações..."
            style={{ width: "100%", background: theme.inputBg, border: `1px solid ${theme.border}`, borderRadius: 10, padding: "8px 12px 8px 34px", color: theme.text, fontSize: 14, outline: "none", fontFamily: "inherit" }} />
        </div>
        <button onClick={createNote}
          style={{ background: "var(--primary)", border: "none", color: "#fff", borderRadius: 10, padding: "9px 20px", cursor: "pointer", fontSize: 14, fontWeight: 700, boxShadow: "0 4px 16px var(--primary-ring)", whiteSpace: "nowrap" }}>
          <Plus size={16} aria-hidden /> Nova Anotação
        </button>
      </div>
      {loading ? (
        <SkeletonList rows={5} />
      ) : filteredNotes.length === 0 ? (
        <EmptyState
          icon={FileText}
          title={searchNotes ? "Nenhuma nota encontrada" : "Nenhuma anotação ainda"}
          description={searchNotes ? "Tente outro termo de busca." : "Clique em “Nova Anotação” acima para começar a escrever."}
        />
      ) : (
        <div style={{ padding: "0 24px 24px", display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))", gap: 12 }}>
          {filteredNotes.map((note) => (
            <div key={note.id} onClick={() => setSelectedNote(note)}
              style={{ padding: 16, borderRadius: 12, border: `1px solid ${theme.border}`, background: theme.surface, cursor: "pointer", transition: "all 0.15s" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
                {note.pinned && <span>📌</span>}
                <span style={{ fontSize: 15, fontWeight: 700, color: theme.text, flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{note.title || "Sem título"}</span>
              </div>
              <div style={{ fontSize: 12, color: theme.textSecondary, lineHeight: 1.5, maxHeight: 60, overflow: "hidden" }}>
                {(note.content || "").replace(/<[^>]*>/g, "").slice(0, 120) || "Nota vazia..."}
              </div>
              <div style={{ fontSize: 10, color: theme.textMuted, marginTop: 8 }}>{new Date(note.updatedAt).toLocaleDateString("pt-BR")}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// Dias da semana (v = valor de Date.getDay(): 0=Dom … 6=Sáb).
const WEEKDAYS = [
  { v: 1, label: "Seg", full: "Segunda" },
  { v: 2, label: "Ter", full: "Terça" },
  { v: 3, label: "Qua", full: "Quarta" },
  { v: 4, label: "Qui", full: "Quinta" },
  { v: 5, label: "Sex", full: "Sexta" },
  { v: 6, label: "Sáb", full: "Sábado" },
  { v: 0, label: "Dom", full: "Domingo" },
];

/** Texto curto dos dias: "Todo dia" quando é a semana inteira, senão "Seg, Qua, Sex". */
function daysLabel(days: number[] | undefined): string {
  if (!days || days.length >= 7) return "Todo dia";
  return WEEKDAYS.filter((d) => days.includes(d.v)).map((d) => d.label).join(", ");
}

/** Chips selecionáveis dos dias da semana. */
function DayChips({ value, onChange, theme }: { value: number[]; onChange: (days: number[]) => void; theme: Theme }) {
  const toggle = (d: number) => onChange(value.includes(d) ? value.filter((x) => x !== d) : [...value, d]);
  return (
    <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
      {WEEKDAYS.map((d) => {
        const on = value.includes(d.v);
        return (
          <button key={d.v} type="button" onClick={() => toggle(d.v)} aria-pressed={on}
            style={{ padding: "5px 10px", borderRadius: 8, border: `1px solid ${on ? "var(--primary)" : theme.inputBorder}`, background: on ? "var(--primary)" : theme.inputBg, color: on ? "#fff" : theme.textSecondary, fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>
            {d.label}
          </button>
        );
      })}
    </div>
  );
}

function RoutineTab({ theme }: { theme: Theme; currentUser: User }) {
  const ALL_DAYS = [0, 1, 2, 3, 4, 5, 6];
  const [items, setItems] = useState<RoutineItem[]>([]);
  const [checks, setChecks] = useState<Pick<RoutineCheck, "routineItemId" | "checkDate">[]>([]);
  const [history, setHistory] = useState<RoutineHistoryDay[]>([]);
  const [newTitle, setNewTitle] = useState("");
  const [newDays, setNewDays] = useState<number[]>(ALL_DAYS);
  const [loading, setLoading] = useState(true);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState("");
  const [editDays, setEditDays] = useState<number[]>(ALL_DAYS);
  const [routineView, setRoutineView] = useState<"hoje" | "semana">("hoje");

  const today = new Date().toLocaleDateString("en-CA");
  const todayDow = new Date().getDay();
  const todayFormatted = new Date().toLocaleDateString("pt-BR", { weekday: "long", day: "numeric", month: "long" });

  useEffect(() => { loadRoutines(); loadHistory(); }, []);

  const loadRoutines = async () => { setLoading(true); try { const data = await api.getRoutines(today); setItems(data.items); setChecks(data.checks); } catch {} finally { setLoading(false); } };
  const loadHistory = async () => { try { const data = await api.getRoutineHistory(7); setHistory(data.history); } catch {} };

  const isChecked = (itemId: string) => checks.some((c) => c.routineItemId === itemId);
  const daysOf = (item: RoutineItem) => (item.days && item.days.length ? item.days : ALL_DAYS);

  const toggleCheck = async (itemId: string) => {
    const wasChecked = isChecked(itemId);
    if (wasChecked) {
      setChecks(checks.filter((c) => c.routineItemId !== itemId));
    } else {
      setChecks([...checks, { routineItemId: itemId, checkDate: today }]);
    }
    await api.toggleRoutineCheck(itemId, today);
    loadHistory();
  };

  const addItem = async () => {
    if (!newTitle.trim()) return;
    try { const created = await api.createRoutineItem({ title: newTitle.trim(), days: newDays }); setItems([...items, created]); setNewTitle(""); setNewDays(ALL_DAYS); loadHistory(); } catch {}
  };

  const deleteItem = async (id: string) => {
    try { await api.deleteRoutineItem(id); setItems(items.filter((i) => i.id !== id)); setChecks(checks.filter((c) => c.routineItemId !== id)); loadHistory(); } catch {}
  };

  const startEdit = (item: RoutineItem) => { setEditingId(item.id); setEditTitle(item.title); setEditDays(daysOf(item)); };
  const cancelEdit = () => { setEditingId(null); };

  const saveEdit = async (id: string) => {
    if (!editTitle.trim()) { setEditingId(null); return; }
    try { const updated = await api.updateRoutineItem(id, { title: editTitle.trim(), days: editDays }); setItems(items.map((i) => (i.id === updated.id ? updated : i))); } catch {}
    setEditingId(null);
  };

  const todaysItems = items.filter((i) => daysOf(i).includes(todayDow));
  const completedToday = todaysItems.filter((i) => isChecked(i.id)).length;
  const totalItems = todaysItems.length;
  const pct = totalItems > 0 ? Math.round((completedToday / totalItems) * 100) : 0;

  // Bloco editor compartilhado (usado quando um hábito está em edição).
  const editorCard = (id: string) => (
    <div style={{ padding: 12, borderRadius: 10, border: `1px solid var(--primary)`, marginBottom: 6, background: theme.inputBg }}>
      <input autoFocus value={editTitle} onChange={(e) => setEditTitle(e.target.value)}
        onKeyDown={(e) => { if (e.key === "Enter") saveEdit(id); if (e.key === "Escape") cancelEdit(); }}
        style={{ width: "100%", background: theme.surface, border: `1px solid ${theme.inputBorder}`, borderRadius: 6, padding: "8px 10px", color: theme.text, fontSize: 14, outline: "none", fontFamily: "inherit", marginBottom: 10 }} />
      <div style={{ fontSize: 12, color: theme.textMuted, marginBottom: 6 }}>Dias da semana</div>
      <div style={{ marginBottom: 12 }}><DayChips value={editDays} onChange={setEditDays} theme={theme} /></div>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <button onClick={() => saveEdit(id)} style={{ background: "var(--primary)", color: "#fff", border: "none", borderRadius: 8, padding: "7px 16px", fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>Salvar</button>
        <button onClick={cancelEdit} style={{ background: theme.inputBg, color: theme.textSecondary, border: `1px solid ${theme.border}`, borderRadius: 8, padding: "7px 12px", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>Cancelar</button>
        <div style={{ flex: 1 }} />
        <button onClick={() => deleteItem(id)} style={{ background: "none", border: "none", color: "#E2445C", cursor: "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit" }}>Excluir</button>
      </div>
    </div>
  );

  // Linha de hábito. showCheck=true no painel de hoje (com bolinha de concluir).
  const habitRow = (item: RoutineItem, showCheck: boolean) => {
    if (editingId === item.id) return <div key={item.id}>{editorCard(item.id)}</div>;
    const checked = showCheck && isChecked(item.id);
    return (
      <div key={item.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 16px", borderRadius: 10, border: `1px solid ${theme.border}`, marginBottom: 6, background: checked ? theme.badgeBg("#00C875") : "transparent", transition: "all 0.15s" }}>
        {showCheck && (
          <button onClick={() => toggleCheck(item.id)}
            style={{ width: 22, height: 22, borderRadius: 6, border: `2px solid ${checked ? "#00C875" : theme.textMuted}`, background: checked ? "#00C875" : "transparent", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", padding: 0, flexShrink: 0 }}>
            {checked && <span style={{ color: "#fff", fontSize: 13 }}>✓</span>}
          </button>
        )}
        <span onClick={() => startEdit(item)}
          style={{ flex: 1, fontSize: 14, fontWeight: 500, color: checked ? theme.textMuted : theme.text, textDecoration: checked ? "line-through" : "none", cursor: "text" }}>{item.title}</span>
        <span style={{ fontSize: 11, color: theme.textMuted, flexShrink: 0 }}>{daysLabel(daysOf(item))}</span>
        <button onClick={() => startEdit(item)} aria-label="Editar" style={{ background: "none", border: "none", color: theme.textMuted, cursor: "pointer", padding: 4, display: "flex", flexShrink: 0 }}><Pencil size={14} /></button>
        <button onClick={() => deleteItem(item.id)} aria-label="Excluir" style={{ background: "none", border: "none", color: theme.textMuted, cursor: "pointer", fontSize: 16, opacity: 0.4, flexShrink: 0 }}>×</button>
      </div>
    );
  };

  if (loading) return (
    <div style={{ padding: 24, maxWidth: 500, margin: "0 auto" }}>
      <div style={{ textAlign: "center", marginBottom: 24 }}>
        <Skeleton width={120} height={12} style={{ margin: "0 auto 10px" }} />
        <Skeleton width={80} height={36} rounded={10} style={{ margin: "0 auto" }} />
      </div>
      <SkeletonList rows={4} />
    </div>
  );

  return (
    <div style={{ padding: 24 }}>
      {/* Alternador Hoje / Semana */}
      <div style={{ display: "flex", gap: 6, justifyContent: "center", marginBottom: 20 }}>
        {(["hoje", "semana"] as const).map((v) => (
          <button key={v} onClick={() => setRoutineView(v)}
            style={{ padding: "7px 18px", borderRadius: 9, border: `1px solid ${routineView === v ? "var(--primary)" : theme.border}`, background: routineView === v ? "var(--primary)" : "transparent", color: routineView === v ? "#fff" : theme.textSecondary, fontSize: 13, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>
            {v === "hoje" ? "Hoje" : "Semana"}
          </button>
        ))}
      </div>

      {routineView === "hoje" ? (
        <>
          <div style={{ textAlign: "center", marginBottom: 24 }}>
            <div style={{ fontSize: 13, color: theme.textMuted, textTransform: "capitalize" }}>{todayFormatted}</div>
            <div style={{ fontSize: 40, fontWeight: 800, color: pct === 100 ? "#00C875" : "var(--primary)", marginTop: 4 }}>{pct}%</div>
            <div style={{ maxWidth: 300, margin: "8px auto 0", height: 6, borderRadius: 6, background: theme.inputBg }}>
              <div style={{ width: `${pct}%`, height: "100%", borderRadius: 6, background: pct === 100 ? "#00C875" : "var(--primary)", transition: "width 0.3s" }} />
            </div>
            <div style={{ fontSize: 12, color: theme.textSecondary, marginTop: 4 }}>{completedToday} de {totalItems} concluídos hoje</div>
          </div>

          <div style={{ maxWidth: 500, margin: "0 auto" }}>
            {todaysItems.length === 0 && (
              <EmptyState
                icon={Repeat}
                title="Nada na rotina de hoje"
                description="Adicione um hábito abaixo e escolha em quais dias ele vale."
                size="sm"
              />
            )}
            {todaysItems.map((item) => habitRow(item, true))}

            <div style={{ marginTop: 12, padding: 12, borderRadius: 10, border: `1px dashed ${theme.border}` }}>
              <div style={{ display: "flex", gap: 8 }}>
                <input value={newTitle} onChange={(e) => setNewTitle(e.target.value)} onKeyDown={(e) => e.key === "Enter" && addItem()} placeholder="Novo hábito..."
                  style={{ flex: 1, background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 8, padding: "10px 14px", color: theme.text, fontSize: 13, outline: "none", fontFamily: "inherit" }} />
                <button onClick={addItem} style={{ background: "var(--primary)", border: "none", borderRadius: 8, color: "#fff", padding: "10px 16px", cursor: "pointer", fontSize: 14, fontWeight: 700 }}>+</button>
              </div>
              <div style={{ marginTop: 10, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                <span style={{ fontSize: 12, color: theme.textMuted }}>Dias:</span>
                <DayChips value={newDays} onChange={setNewDays} theme={theme} />
              </div>
            </div>
          </div>

          {history.length > 0 && (
            <div style={{ maxWidth: 500, margin: "24px auto 0" }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: theme.textSecondary, marginBottom: 10 }}>Últimos 7 dias</div>
              <div style={{ display: "flex", gap: 6, justifyContent: "space-between" }}>
                {history.map((day) => {
                  const dayPct = day.total > 0 ? Math.round((day.completed / day.total) * 100) : 0;
                  const isToday = day.date === today;
                  return (
                    <div key={day.date} style={{ textAlign: "center", flex: 1 }}>
                      <div style={{ fontSize: 10, color: isToday ? "var(--primary)" : theme.textMuted, fontWeight: isToday ? 700 : 400, marginBottom: 4 }}>
                        {new Date(day.date + "T12:00:00").toLocaleDateString("pt-BR", { weekday: "short" })}
                      </div>
                      <div style={{ height: 40, borderRadius: 6, background: theme.inputBg, position: "relative", overflow: "hidden" }}>
                        <div style={{ position: "absolute", bottom: 0, width: "100%", height: `${dayPct}%`, background: dayPct === 100 ? "#00C875" : "var(--primary)", borderRadius: 6, transition: "height 0.3s" }} />
                      </div>
                      <div style={{ fontSize: 10, color: theme.textMuted, marginTop: 2 }}>{dayPct}%</div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </>
      ) : (
        <div style={{ maxWidth: 560, margin: "0 auto" }}>
          {/* Visão semanal: cada dia com os hábitos agendados */}
          <div style={{ marginBottom: 24 }}>
            {WEEKDAYS.map((d) => {
              const dayItems = items.filter((i) => daysOf(i).includes(d.v));
              const isTodayCol = d.v === todayDow;
              return (
                <div key={d.v} style={{ marginBottom: 8, padding: "12px 14px", borderRadius: 10, border: `1px solid ${isTodayCol ? "var(--primary)" : theme.border}`, background: isTodayCol ? "var(--primary-soft)" : "transparent" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: dayItems.length ? 8 : 0 }}>
                    <span style={{ fontSize: 14, fontWeight: 700, color: isTodayCol ? "var(--primary)" : theme.text }}>{d.full}</span>
                    {isTodayCol && <span style={{ fontSize: 10, fontWeight: 700, color: "#fff", background: "var(--primary)", borderRadius: 6, padding: "1px 7px" }}>hoje</span>}
                    <span style={{ marginLeft: "auto", fontSize: 11, color: theme.textMuted }}>{dayItems.length} {dayItems.length === 1 ? "hábito" : "hábitos"}</span>
                  </div>
                  {dayItems.length === 0 ? (
                    <span style={{ fontSize: 12, color: theme.textMuted }}>—</span>
                  ) : (
                    <div style={{ display: "flex", flexDirection: "column", gap: 3 }}>
                      {dayItems.map((i) => (
                        <span key={i.id} style={{ fontSize: 13, color: theme.textSecondary }}>• {i.title}</span>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          {/* Gerenciar: todos os hábitos, editar dias / excluir */}
          <div style={{ fontSize: 13, fontWeight: 700, color: theme.textSecondary, marginBottom: 10 }}>Todos os hábitos</div>
          {items.length === 0 ? (
            <EmptyState icon={Repeat} title="Nenhum hábito ainda" description="Crie hábitos na aba Hoje." size="sm" />
          ) : (
            items.map((item) => habitRow(item, false))
          )}
        </div>
      )}
    </div>
  );
}

