// ——— Main App ———
export default function TaskManager() {
  // Sistema é light-only — sem mode toggle
  const theme = useMemo(() => getTheme("light"), []);
  const isMobile = useIsMobile();

  const [users, setUsers] = useState<User[]>([]);
  const [tags, setTags] = useState<Tag[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [projects, setProjects] = useState<Project[]>([]);
  const [taskGroups, setTaskGroups] = useState<TaskGroup[]>([]);
  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
  const [activeWorkspace, setActiveWorkspace] = useState("all");
  const [tasks, setTasks] = useState<Task[]>([]);
  const [activeProject, setActiveProject] = useState("all");
  const [detailTask, setDetailTask] = useState<Task | null>(null);
  const [search, setSearch] = useState("");
  const [showNewProject, setShowNewProject] = useState(false);
  const [newProjectName, setNewProjectName] = useState("");
  const [showNewGroup, setShowNewGroup] = useState(false);
  const [newGroupName, setNewGroupName] = useState("");
  const [expandedWs, setExpandedWs] = useState<Set<string>>(new Set());
  const [editingProjName, setEditingProjName] = useState(false);
  const [projNameDraft, setProjNameDraft] = useState("");
  const [filterStatus, setFilterStatus] = useState("all");
  const [showAdmin, setShowAdmin] = useState(false);
  const [expandedTasks, setExpandedTasks] = useState<Set<string>>(new Set());
  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set());
  const [activeView, setActiveView] = useState<"tasks" | "personal" | "my-tasks" | "content" | "notes" | "routine" | "assets" | "transcricoes">("personal");
  const [personalTab, setPersonalTab] = useState<"minhas-tarefas" | "transcricoes" | "agenda">("minhas-tarefas");
  const [groupOrder, setGroupOrder] = useState<string[]>(() => {
    if (typeof window !== "undefined") {
      const saved = localStorage.getItem("nexia-group-order");
      return saved ? JSON.parse(saved) : [];
    }
    return [];
  });
  const [toasts, setToasts] = useState<{ id: string; message: string; type: "error" | "success" }[]>([]);
  const [confirm, setConfirm] = useState<{ title: string; description?: string; onConfirm: () => void | Promise<void> } | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false); // mobile drawer
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false); // recolher (desktop)
  const [personalExpanded, setPersonalExpanded] = useState(false); // submenu "Minha Área" fechado por padrão
  const [shortcutsOpen, setShortcutsOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [tasksViewMode, setTasksViewMode] = useState<"list" | "kanban">(() => {
    if (typeof window === "undefined") return "list";
    const saved = localStorage.getItem("ordum-tasks-view");
    return saved === "kanban" ? "kanban" : "list";
  });
  useEffect(() => {
    if (typeof window !== "undefined") localStorage.setItem("ordum-tasks-view", tasksViewMode);
  }, [tasksViewMode]);
  const searchRef = useRef<HTMLInputElement>(null);

  const showToast = useCallback((message: string, type: "error" | "success" = "error") => {
    const id = Math.random().toString(36).slice(2);
    setToasts((prev) => [...prev, { id, message, type }]);
    setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), 4000);
  }, []);

  const dndSensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 8 } }));

  const isAdmin = currentUser?.role === "admin";
  const isEditor = currentUser?.role === "editor";
  const canEdit = isAdmin || isEditor;

  // A API já devolve só projetos/tarefas acessíveis (admin vê tudo via RPC/select).
  // Aqui aplicamos apenas o filtro do workspace ativo.
  const visibleProjects = projects.filter((p) => {
    if (activeWorkspace !== "all" && p.workspaceId !== activeWorkspace) return false;
    return true;
  });

  const filteredTasks = tasks.filter((t) => {
    const proj = projects.find((p) => p.id === t.projectId);
    if (!proj) return false;
    if (activeWorkspace !== "all" && proj.workspaceId !== activeWorkspace) return false;
    if (activeProject !== "all" && t.projectId !== activeProject) return false;
    if (filterStatus !== "all" && t.status !== filterStatus) return false;
    if (search && !t.title.toLowerCase().includes(search.toLowerCase())) return false;
    return true;
  });

  /** Grupos do projeto aberto, na ordem salva. */
  const activeProjectGroups = useMemo(
    () => taskGroups.filter((g) => g.projectId === activeProject).sort((a, b) => a.position - b.position),
    [taskGroups, activeProject]
  );

  const groups: Group[] = useMemo(() => {
    // Dentro de um projeto: os grupos são os task_groups dele.
    if (activeProject !== "all") {
      const proj = projects.find((p) => p.id === activeProject);
      if (!proj) return [];
      const byGroup = new Map<string, Task[]>();
      const semGrupo: Task[] = [];
      filteredTasks.forEach((t) => {
        if (t.groupId) {
          const list = byGroup.get(t.groupId) ?? [];
          list.push(t);
          byGroup.set(t.groupId, list);
        } else {
          semGrupo.push(t);
        }
      });
      const result: Group[] = activeProjectGroups.map((g) => ({
        id: g.id,
        name: g.name,
        color: g.color,
        icon: proj.icon,
        tasks: byGroup.get(g.id) ?? [],
        projectId: proj.id,
        kind: "group" as const,
      }));
      // Projeto sem nenhum grupo ainda: cai no comportamento antigo (uma lista só).
      if (result.length === 0) {
        return [{ id: proj.id, name: proj.name, color: proj.color, icon: proj.icon, tasks: filteredTasks, projectId: proj.id, kind: "project" as const, ungrouped: true }];
      }
      if (semGrupo.length > 0) {
        result.push({ id: `__ungrouped__${proj.id}`, name: "Sem grupo", color: "#9AA5B1", icon: proj.icon, tasks: semGrupo, projectId: proj.id, kind: "group" as const, ungrouped: true });
      }
      return result;
    }
    const groupMap = new Map<string, Group>();
    filteredTasks.forEach((t) => {
      const proj = projects.find((p) => p.id === t.projectId);
      if (!proj) return;
      if (!groupMap.has(proj.id)) {
        groupMap.set(proj.id, { id: proj.id, name: proj.name, color: proj.color, icon: proj.icon, tasks: [], projectId: proj.id, kind: "project" });
      }
      groupMap.get(proj.id)!.tasks.push(t);
    });
    const unsorted = Array.from(groupMap.values());
    if (groupOrder.length === 0) return unsorted;
    return unsorted.sort((a, b) => {
      const ai = groupOrder.indexOf(a.id);
      const bi = groupOrder.indexOf(b.id);
      if (ai === -1 && bi === -1) return 0;
      if (ai === -1) return 1;
      if (bi === -1) return -1;
      return ai - bi;
    });
  }, [filteredTasks, activeProject, projects, groupOrder, activeProjectGroups]);

  const handleGroupDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    const ids = groups.map((g) => g.id);
    const oldIndex = ids.indexOf(active.id as string);
    const newIndex = ids.indexOf(over.id as string);
    if (oldIndex === -1 || newIndex === -1) return;
    const newOrder = arrayMove(ids, oldIndex, newIndex);

    // Dentro de um projeto a ordem é dos grupos de verdade — vai pro banco.
    if (activeProject !== "all") {
      const persistidos = newOrder.filter((id) => activeProjectGroups.some((g) => g.id === id));
      if (persistidos.length === 0) return;
      setTaskGroups((prev) =>
        prev.map((g) => {
          const i = persistidos.indexOf(g.id);
          return i === -1 ? g : { ...g, position: i };
        })
      );
      api.reorderTaskGroups(activeProject, persistidos).catch(() => showToast("Erro ao reordenar grupos"));
      return;
    }

    setGroupOrder(newOrder);
    localStorage.setItem("nexia-group-order", JSON.stringify(newOrder));
  };

  const toggleExpandTask = (taskId: string) => {
    setExpandedTasks((prev) => {
      const next = new Set(prev);
      if (next.has(taskId)) next.delete(taskId); else next.add(taskId);
      return next;
    });
  };

  const toggleCollapseGroup = (groupId: string) => {
    setCollapsedGroups((prev) => {
      const next = new Set(prev);
      if (next.has(groupId)) next.delete(groupId); else next.add(groupId);
      return next;
    });
  };

  const loadData = useCallback(async () => {
    try {
      const [u, p, t, tg, ws, grp] = await Promise.all([
        api.getUsers(),
        api.getProjects(),
        api.getTasks(),
        api.getTags(),
        api.getWorkspaces(),
        api.getTaskGroups(),
      ]);
      setUsers(u);
      setProjects(p.map((x) => ({ ...x, sharedWith: x.sharedWith || [] })));
      setTasks(t);
      setTags(tg);
      setWorkspaces(ws);
      setTaskGroups(grp);
    } catch { showToast("Erro ao carregar dados"); }
  }, []);

  // Auto-login from saved token.
  // Só descarta a sessão se o servidor disser que o token não presta (401/403).
  // Servidor reiniciando, deploy no ar ou wifi oscilando não podem deslogar
  // ninguém: nesses casos espera e tenta de novo.
  useEffect(() => {
    if (currentUser) return;
    if (!api.hasToken()) return;
    let cancelado = false;
    let tentativa = 0;

    const tentar = () => {
      api.me()
        .then((u) => { if (!cancelado) setCurrentUser(u); })
        .catch((err) => {
          if (cancelado) return;
          const status = err instanceof ApiRequestError ? err.status : 0;
          if (status === 401 || status === 403) { api.logout(); return; }
          tentativa += 1;
          if (tentativa <= 6) setTimeout(tentar, Math.min(1000 * 2 ** tentativa, 15_000));
        });
    };
    tentar();
    return () => { cancelado = true; };
  }, [currentUser]);

  useEffect(() => { if (currentUser) loadData(); }, [currentUser, loadData]);

  // URL por tarefa: /?tarefa=<id> abre o painel direto.
  // O alvo é lido UMA vez, na primeira render — antes que o efeito de
  // sincronia abaixo limpe o parâmetro por ainda não haver tarefa aberta.
  const [alvoDoLink] = useState<string | null>(() =>
    typeof window === "undefined" ? null : new URL(window.location.href).searchParams.get("tarefa")
  );
  const linkResolvidoRef = useRef(!alvoDoLink);

  // Abre a tarefa apontada pela URL assim que a lista chega.
  useEffect(() => {
    if (linkResolvidoRef.current || !alvoDoLink || !tasks.length) return;
    const t = tasks.find((x) => x.id === alvoDoLink);
    linkResolvidoRef.current = true;
    if (t) setDetailTask(t);
    else showToast("Tarefa do link não encontrada (pode ter sido excluída)");
  }, [tasks, alvoDoLink]);

  // Mantém a barra de endereço em dia pra copiar/compartilhar. Só age depois
  // que o link inicial foi resolvido, senão apagaria o parâmetro antes da hora.
  useEffect(() => {
    if (!linkResolvidoRef.current) return;
    const url = new URL(window.location.href);
    if (detailTask?.id === url.searchParams.get("tarefa")) return;
    if (detailTask) url.searchParams.set("tarefa", detailTask.id);
    else url.searchParams.delete("tarefa");
    window.history.replaceState(null, "", url.toString());
  }, [detailTask]);

  const updateTask = async (updated: Task) => {
    if (!canEdit) return;
    setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
    if (detailTask && detailTask.id === updated.id) setDetailTask(updated);
    // Título vazio = usuário apagou pra reescrever. Mantém na tela e espera
    // ele terminar; a API rejeitaria com 400 a cada tecla.
    if (!updated.title.trim()) return;
    try {
      await api.updateTask(updated.id, {
        title: updated.title,
        description: updated.description,
        status: updated.status,
        priority: updated.priority,
        deadline: updated.deadline,
        startDate: updated.startDate,
        estimateHours: updated.estimateHours,
        tagIds: updated.tagIds,
        projectId: updated.projectId,
        groupId: updated.groupId,
        assignedTo: updated.assignedTo,
        link: updated.link,
        checked: updated.checked,
        checklist: updated.checklist,
        subtasks: updated.subtasks,
      });
    } catch (err) {
      showToast(err instanceof Error ? err.message : "Erro ao salvar tarefa");
    }
  };

  const deleteTask = (task: Task) => {
    if (!canEdit) return;
    setConfirm({
      title: `Excluir "${task.title}"?`,
      description: "A tarefa sai da lista. Ela fica recuperável no banco.",
      onConfirm: async () => {
        setConfirm(null);
        const backup = tasks;
        setTasks((prev) => prev.filter((t) => t.id !== task.id));
        if (detailTask?.id === task.id) setDetailTask(null);
        try {
          await api.deleteTask(task.id);
          showToast("Tarefa excluída", "success");
        } catch (err) {
          setTasks(backup);
          showToast(err instanceof Error ? err.message : "Erro ao excluir tarefa");
        }
      },
    });
  };

  const addTask = async () => {
    if (!canEdit || !currentUser) return;
    const projectId = activeProject === "all" ? visibleProjects[0]?.id : activeProject;
    if (!projectId) { showToast("Nenhum projeto disponível. Peça ao admin para compartilhar um projeto com você."); return; }
    try {
      const nt = await api.createTask({ title: "Nova tarefa", status: "todo", priority: "medium", projectId, assignedTo: currentUser.id });
      setTasks((prev) => [nt, ...prev]);
      setDetailTask(nt);
    } catch { showToast("Erro ao criar tarefa"); }
  };

  const addTaskInline = async (title: string, projectId: string, groupId: string | null) => {
    if (!canEdit || !currentUser) return;
    try {
      const nt = await api.createTask({ title, status: "todo", priority: "medium", projectId, groupId, assignedTo: currentUser.id });
      setTasks((prev) => [...prev, nt]);
    } catch { showToast("Erro ao criar tarefa"); }
  };

  /** Cria "Nova tarefa" no grupo e abre o drawer pra editar imediatamente. */
  const addTaskInGroup = async (projectId: string, groupId: string | null, collapseKey?: string) => {
    if (!canEdit || !currentUser) return;
    try {
      const nt = await api.createTask({ title: "Nova tarefa", status: "todo", priority: "medium", projectId, groupId, assignedTo: currentUser.id });
      setTasks((prev) => [nt, ...prev]);
      // Garante que o grupo correspondente fica expandido
      setCollapsedGroups((prev) => {
        const next = new Set(prev);
        next.delete(collapseKey ?? groupId ?? projectId);
        return next;
      });
      setDetailTask(nt);
    } catch { showToast("Erro ao criar tarefa"); }
  };

  /** Cria um grupo DENTRO do projeto aberto (não um projeto novo na sidebar). */
  const addTaskGroup = async (nameArg?: string) => {
    const rawName = (nameArg ?? newGroupName).trim();
    if (!rawName || !canEdit) return;
    // Na visão "Todos" não existe projeto dono — cai no fluxo antigo de projeto.
    if (activeProject === "all") { await addProject(rawName); return; }
    try {
      const ng = await api.createTaskGroup({ projectId: activeProject, name: rawName });
      setTaskGroups((prev) => [...prev, ng]);
      showToast(`Grupo "${rawName}" criado`, "success");
    } catch (err) {
      showToast(err instanceof Error ? err.message : "Erro ao criar grupo");
    }
    setNewGroupName(""); setShowNewGroup(false);
  };

  const renameTaskGroup = async (id: string, name: string) => {
    const backup = taskGroups;
    setTaskGroups((prev) => prev.map((g) => (g.id === id ? { ...g, name } : g)));
    try {
      await api.updateTaskGroup(id, { name });
    } catch (err) {
      setTaskGroups(backup);
      showToast(err instanceof Error ? err.message : "Erro ao renomear grupo");
    }
  };

  const deleteTaskGroup = (group: Group) => {
    if (!canEdit) return;
    setConfirm({
      title: `Excluir o grupo "${group.name}"?`,
      description: group.tasks.length > 0
        ? `As ${group.tasks.length} tarefas continuam no projeto, em "Sem grupo".`
        : "O grupo some do quadro.",
      onConfirm: async () => {
        setConfirm(null);
        const backupGroups = taskGroups;
        const backupTasks = tasks;
        setTaskGroups((prev) => prev.filter((g) => g.id !== group.id));
        setTasks((prev) => prev.map((t) => (t.groupId === group.id ? { ...t, groupId: null } : t)));
        try {
          await api.deleteTaskGroup(group.id);
          showToast("Grupo excluído", "success");
        } catch (err) {
          setTaskGroups(backupGroups);
          setTasks(backupTasks);
          showToast(err instanceof Error ? err.message : "Erro ao excluir grupo");
        }
      },
    });
  };

  const addProject = async (nameArg?: string) => {
    const rawName = (nameArg ?? newProjectName).trim();
    if (!rawName || !canEdit || !currentUser) return;
    const colors = ["#0F4C5C", "#15708C", "#E07A52", "#00C875", "#FDAB3D", "#579BFC", "#FF78CB", "#1ABC9C"];
    const icons = ["📌", "⚡", "💡", "🎯", "🔥", "🌟", "🚀", "🌐"];
    const color = colors[Math.floor(Math.random() * colors.length)];
    const icon = icons[Math.floor(Math.random() * icons.length)];
    try {
      const np = await api.createProject({
        name: rawName,
        color,
        icon,
        workspaceId: activeWorkspace !== "all" ? activeWorkspace : undefined,
      });
      setProjects((prev) => [...prev, { ...np, ownerId: np.ownerId || currentUser.id, sharedWith: np.sharedWith || [] }]);
      showToast(`Grupo "${rawName}" criado`, "success");
    } catch (err) { showToast(err instanceof Error ? err.message : "Erro ao criar grupo"); }
    setNewProjectName(""); setShowNewProject(false);
    setNewGroupName(""); setShowNewGroup(false);
  };

  const renameProjectName = async () => {
    if (!activeProj) return;
    const name = projNameDraft.trim();
    setEditingProjName(false);
    if (!name || name === activeProj.name) return;
    setProjects((prev) => prev.map((p) => (p.id === activeProj.id ? { ...p, name } : p)));
    try { await api.renameProject(activeProj.id, name); showToast("Projeto renomeado", "success"); }
    catch { showToast("Erro ao renomear"); }
  };

  const deleteProject = (projId: string) => {
    if (!isAdmin) return;
    const proj = projects.find((p) => p.id === projId);
    const taskCount = tasks.filter((t) => t.projectId === projId).length;
    setConfirm({
      title: `Apagar projeto "${proj?.name}"?`,
      description: taskCount > 0
        ? `Esta ação também removerá ${taskCount} tarefa${taskCount > 1 ? "s" : ""} associada${taskCount > 1 ? "s" : ""}. Tudo fica recuperável via banco.`
        : "O projeto será arquivado.",
      onConfirm: async () => {
        try {
          await api.deleteProject(projId);
          setProjects((prev) => prev.filter((p) => p.id !== projId));
          setTasks((prev) => prev.filter((t) => t.projectId !== projId));
          if (activeProject === projId) setActiveProject("all");
          showToast(`Projeto "${proj?.name}" apagado`, "success");
        } catch { showToast("Erro ao apagar projeto"); }
        setConfirm(null);
      },
    });
  };

  const counts: Record<string, number> = { all: filteredTasks.length };
  visibleProjects.forEach((p) => { counts[p.id] = tasks.filter((t) => t.projectId === p.id).length; });
  const activeProj = projects.find((p) => p.id === activeProject);
  const activeWs = workspaces.find((w) => w.id === activeWorkspace);

  // Título da página exibido na barra superior (views simples; tasks/content têm header próprio)
  const pageTitle =
    activeView === "personal" ? "Minha Área" :
    activeView === "my-tasks" ? "Minhas tarefas" :
    activeView === "notes" ? "Anotações" :
    activeView === "routine" ? "Rotina" :
    activeView === "transcricoes" ? "Transcrições" :
    activeView === "assets" ? "Assets" : "";
  const pageSubtitle = (activeView === "personal" || activeView === "my-tasks") ? (currentUser?.name ?? "") : "";

  const handleLogin = async (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    api.logout();
    setUsers([]);
    setProjects([]);
    setTasks([]);
  };

  const shortcuts: Shortcut[] = useMemo(() => [
    { combo: "n", description: "Nova tarefa", handler: (e) => { e.preventDefault(); if (canEdit) addTask(); } },
    { combo: "/", description: "Focar busca", handler: (e) => { e.preventDefault(); searchRef.current?.focus(); } },
    { combo: "shift+/", description: "Mostrar atalhos", handler: (e) => { e.preventDefault(); setShortcutsOpen(true); } },
    { combo: "Escape", description: "Fechar modais", handler: () => { setShortcutsOpen(false); setSidebarOpen(false); setDetailTask(null); }, allowInInputs: true },
  ], [canEdit]); // eslint-disable-line react-hooks/exhaustive-deps

  useKeyboardShortcuts(shortcuts, !!currentUser);

  if (!currentUser) {
    return <LoginScreen onLogin={handleLogin} />;
  }

  return (
    <div className="app-shell" style={{ display: "flex", height: "100vh", fontFamily: "inherit", fontSize: 14, lineHeight: 1.43, background: theme.bg, color: theme.text }}>
      <style>{`
        ::-webkit-scrollbar { width: 6px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: var(--scroll-thumb); border-radius: 10px; }
        .task-row:hover { background: var(--surface-hover) !important; }
        .task-row:hover .task-delete-btn { opacity: 1 !important; }
        .task-delete-btn:hover { opacity: 1 !important; transform: scale(1.15); }
        .sidebar-item { transition: all 0.15s; border: none; cursor: pointer; width: 100%; text-align: left; font-family: inherit; }
        .sidebar-item { position: relative; }
        .sidebar-item:hover { background: rgba(244, 239, 226, 0.14) !important; box-shadow: inset 3px 0 0 var(--accent); }
        /* O "···" (apagar projeto) só existe em dispositivos com mouse real.
           Em touch o :hover fica preso depois do toque e o botão aparecia sozinho. */
        @media (hover: hover) and (pointer: fine) {
          .sidebar-item:hover .proj-menu-btn { opacity: 0.6 !important; }
          .sidebar-item:hover .proj-count { opacity: 0 !important; position: absolute !important; }
          .sidebar-item .proj-menu-btn:hover { opacity: 1 !important; color: var(--status-review) !important; }
        }
        @media not all and (hover: hover) {
          .proj-menu-btn { display: none !important; }
        }
        input::placeholder, textarea::placeholder { color: var(--text-muted); }

        /* ── Responsividade: sidebar vira drawer em <=1024px ─────── */
        .menu-toggle { display: none; }
        .sidebar-backdrop { display: none; }
        @media (max-width: 1024px) {
          .menu-toggle { display: inline-flex; }
          .app-sidebar {
            position: fixed !important;
            inset: 0 auto 0 0;
            z-index: 1100;
            transform: translateX(-100%);
            transition: transform 0.25s ease;
            box-shadow: 8px 0 32px rgba(0,0,0,0.18);
          }
          .app-sidebar[data-open="true"] { transform: translateX(0); }
          .sidebar-backdrop {
            display: block;
            position: fixed; inset: 0; z-index: 1099;
            background: var(--overlay); backdrop-filter: blur(4px);
            animation: fadeIn 0.2s ease-out;
          }
        }
        @media (max-width: 768px) {
          .app-header-search { width: 100% !important; }
          .app-header { flex-direction: column !important; align-items: stretch !important; gap: 12px !important; }
        }
      `}</style>

      {/* Backdrop (mobile drawer) */}
      {sidebarOpen && <div className="sidebar-backdrop" onClick={() => setSidebarOpen(false)} aria-hidden />}

      {/* Sidebar */}
      <aside className="app-sidebar" data-open={sidebarOpen ? "true" : "false"} data-collapsed={sidebarCollapsed ? "true" : "false"}
        style={{ width: sidebarCollapsed ? 68 : 260, background: "var(--sidebar)", color: "var(--sidebar-text)", borderRight: `1px solid var(--sidebar-border)`, display: "flex", flexDirection: "column", padding: sidebarCollapsed ? "16px 0" : "20px 0", flexShrink: 0, height: "100%", overflow: "hidden", transition: "width 0.2s ease" }}>
        {sidebarCollapsed ? (
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6, flex: 1, overflowY: "auto", width: "100%" }}>
            <button onClick={() => setSidebarCollapsed(false)} title="Expandir menu" aria-label="Expandir menu" style={railBtnStyle(false)}><PanelLeftOpen size={18} /></button>
            <div style={{ height: 6 }} />
            <button onClick={() => setActiveView("personal")} title="Minha Área" aria-label="Minha Área" style={railBtnStyle(activeView === "personal")}><UserIcon size={18} /></button>
            <button onClick={() => setActiveView("my-tasks")} title="Minhas tarefas" aria-label="Minhas tarefas" style={railBtnStyle(activeView === "my-tasks")}><ListChecks size={18} /></button>
            <button onClick={() => setActiveView("routine")} title="Rotina" aria-label="Rotina" style={railBtnStyle(activeView === "routine")}><Repeat size={18} /></button>
            <button onClick={() => setActiveView("notes")} title="Anotações" aria-label="Anotações" style={railBtnStyle(activeView === "notes" || activeView === "transcricoes")}><Pencil size={18} /></button>
            <button onClick={() => setActiveView("assets")} title="Assets" aria-label="Assets" style={railBtnStyle(activeView === "assets")}><Link2 size={18} /></button>
            {workspaces.length > 0 && <div style={{ width: 24, height: 1, background: "var(--sidebar-border)", margin: "6px 0" }} />}
            {workspaces.map((ws) => (
              <button key={ws.id} onClick={() => { setActiveWorkspace(ws.id); setActiveView("tasks"); setActiveProject("all"); }} title={ws.name} aria-label={ws.name} style={railBtnStyle(activeWorkspace === ws.id)}>
                <span style={{ width: 12, height: 12, borderRadius: "50%", background: ws.color }} />
              </button>
            ))}
            <div style={{ flex: 1 }} />
          </div>
        ) : (
        <>
        <div style={{ padding: "22px 16px 18px", display: "flex", alignItems: "center", justifyContent: "center", position: "relative" }}>
          <ClarezaLogo height={38} forceWhite />
          <button onClick={() => setSidebarCollapsed(true)} aria-label="Recolher menu" title="Recolher menu"
            className="sidebar-collapse-btn"
            style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)", background: "transparent", border: "none", color: "var(--sidebar-text-muted)", cursor: "pointer", display: "flex", padding: 4, borderRadius: 6 }}>
            <PanelLeftClose size={18} />
          </button>
        </div>

        <div style={{ padding: "16px 12px", flex: 1, overflowY: "auto" }}>
          <button className="sidebar-item" onClick={() => { setActiveView("personal"); setPersonalExpanded((v) => !v); }}
            style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 12px", borderRadius: 10, marginBottom: personalExpanded ? 2 : 6, fontSize: 14, fontWeight: 600, background: activeView === "personal" ? "var(--sidebar-active-bg)" : "transparent", color: activeView === "personal" ? "var(--sidebar-active-text)" : "var(--sidebar-text-secondary)", width: "100%", border: "none", cursor: "pointer", fontFamily: "inherit", textAlign: "left" }}>
            <UserIcon size={16} aria-hidden /><span style={{ flex: 1 }}>Minha Área</span>
            <ChevronRight size={14} aria-hidden style={{ transform: personalExpanded ? "rotate(90deg)" : "none", transition: "transform 0.15s", flexShrink: 0, opacity: 0.6 }} />
          </button>

          {personalExpanded && (
            <button className="sidebar-item" onClick={() => { setActiveView("my-tasks"); }}
              style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 12px 8px 34px", borderRadius: 10, marginBottom: 6, fontSize: 13, fontWeight: 500, background: activeView === "my-tasks" ? "var(--sidebar-active-bg)" : "transparent", color: activeView === "my-tasks" ? "var(--sidebar-active-text)" : "var(--sidebar-text-secondary)", width: "100%", border: "none", cursor: "pointer", fontFamily: "inherit", textAlign: "left" }}>
              <ListChecks size={14} aria-hidden /><span style={{ flex: 1 }}>Minhas tarefas</span>
            </button>
          )}

          <button className="sidebar-item" onClick={() => { setActiveView("routine"); }}
            style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 12px", borderRadius: 10, marginBottom: 6, fontSize: 14, fontWeight: 600, background: activeView === "routine" ? "var(--sidebar-active-bg)" : "transparent", color: activeView === "routine" ? "var(--sidebar-active-text)" : "var(--sidebar-text-secondary)", width: "100%", border: "none", cursor: "pointer", fontFamily: "inherit", textAlign: "left" }}>
            <Repeat size={16} aria-hidden /><span style={{ flex: 1 }}>Rotina</span>
          </button>

          <button className="sidebar-item" onClick={() => { setActiveView("notes"); }}
            style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 12px", borderRadius: 10, marginBottom: (activeView === "notes" || activeView === "transcricoes") ? 2 : 6, fontSize: 14, fontWeight: 600, background: activeView === "notes" ? "var(--sidebar-active-bg)" : "transparent", color: activeView === "notes" ? "var(--sidebar-active-text)" : "var(--sidebar-text-secondary)", width: "100%", border: "none", cursor: "pointer", fontFamily: "inherit", textAlign: "left" }}>
            <Pencil size={16} aria-hidden /><span style={{ flex: 1 }}>Anotações</span>
          </button>

          {(activeView === "notes" || activeView === "transcricoes") && (
            <button className="sidebar-item" onClick={() => { setActiveView("transcricoes"); }}
              style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 12px 8px 34px", borderRadius: 10, marginBottom: 6, fontSize: 13, fontWeight: 500, background: activeView === "transcricoes" ? "var(--sidebar-active-bg)" : "transparent", color: activeView === "transcricoes" ? "var(--sidebar-active-text)" : "var(--sidebar-text-secondary)", width: "100%", border: "none", cursor: "pointer", fontFamily: "inherit", textAlign: "left" }}>
              <FileText size={14} aria-hidden /><span style={{ flex: 1 }}>Transcrições</span>
            </button>
          )}

          {currentUser.canAccessContent && (
            <button className="sidebar-item" onClick={() => { setActiveView("content"); }}
              style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 12px", borderRadius: 10, marginBottom: 6, fontSize: 14, fontWeight: 600, background: activeView === "content" ? "var(--sidebar-active-bg)" : "transparent", color: activeView === "content" ? "var(--sidebar-active-text)" : "var(--sidebar-text-secondary)", width: "100%", border: "none", cursor: "pointer", fontFamily: "inherit", textAlign: "left" }}>
              <FileText size={16} aria-hidden /><span style={{ flex: 1 }}>Conteúdo</span>
            </button>
          )}

          <button className="sidebar-item" onClick={() => { setActiveView("assets"); }}
            style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 12px", borderRadius: 10, marginBottom: 6, fontSize: 14, fontWeight: 600, background: activeView === "assets" ? "var(--sidebar-active-bg)" : "transparent", color: activeView === "assets" ? "var(--sidebar-active-text)" : "var(--sidebar-text-secondary)", width: "100%", border: "none", cursor: "pointer", fontFamily: "inherit", textAlign: "left" }}>
            <Link2 size={16} aria-hidden /><span style={{ flex: 1 }}>Assets</span>
          </button>

          {workspaces.length > 0 && (
            <div style={{ padding: "0 8px", marginTop: 8 }}>
              <div style={{ fontSize: 12, color: "var(--sidebar-text-muted)", fontWeight: 600, letterSpacing: 1, textTransform: "uppercase", marginBottom: 6 }}>Workspaces</div>
              {workspaces.map((ws) => {
                // Não usar visibleProjects: ele já filtra pelo workspace ativo e zeraria os outros grupos.
                const wsProjects = projects.filter((p) => p.workspaceId === ws.id);
                const isOpen = expandedWs.has(ws.id);
                return (
                  <div key={ws.id}>
                    <button onClick={() => setExpandedWs((prev) => { const n = new Set(prev); n.has(ws.id) ? n.delete(ws.id) : n.add(ws.id); return n; })}
                      className="sidebar-item"
                      style={{ display: "flex", alignItems: "center", gap: 8, width: "100%", border: "none", textAlign: "left", padding: "9px 10px", borderRadius: 8, marginBottom: 2, fontSize: 14, fontWeight: 600, fontFamily: "inherit", cursor: "pointer", background: "transparent", color: "var(--sidebar-text-secondary)" }}>
                      <ChevronRight size={14} aria-hidden style={{ transform: isOpen ? "rotate(90deg)" : "none", transition: "transform 0.15s", flexShrink: 0, color: "var(--sidebar-text-muted)" }} />
                      <span style={{ width: 9, height: 9, borderRadius: "50%", background: ws.color, flexShrink: 0 }} />
                      <span style={{ flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{ws.name}</span>
                    </button>

                    {isOpen && (
                      <div style={{ marginLeft: 9, paddingLeft: 8, borderLeft: `1px solid var(--sidebar-border)`, marginBottom: 4 }}>
                        {wsProjects.map((proj) => (
                          <div key={proj.id} className="sidebar-item" style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 10px", borderRadius: 8, marginBottom: 2, fontSize: 13, fontWeight: 500, background: (activeView === "tasks" && activeProject === proj.id) ? "var(--sidebar-active-bg)" : "transparent", color: (activeView === "tasks" && activeProject === proj.id) ? "var(--sidebar-active-text)" : "var(--sidebar-text-secondary)", cursor: "pointer", position: "relative" }}
                            onClick={() => { setActiveWorkspace(ws.id); setActiveView("tasks"); setActiveProject(proj.id); }}>
                            <span style={{ width: 8, height: 8, borderRadius: "50%", background: proj.color, flexShrink: 0 }} />
                            <span style={{ flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{proj.name}</span>
                            <span className="proj-count" style={{ fontSize: 11, color: "var(--sidebar-text-muted)", background: "var(--sidebar-input-bg)", padding: "1px 7px", borderRadius: 10, transition: "opacity 0.15s" }}>{counts[proj.id] || 0}</span>
                            {isAdmin && (
                              <button onClick={(e) => { e.stopPropagation(); deleteProject(proj.id); }}
                                className="proj-menu-btn"
                                style={{ background: "none", border: "none", color: "var(--sidebar-text-muted)", cursor: "pointer", fontSize: 16, padding: "0 4px", borderRadius: 4, opacity: 0, transition: "opacity 0.15s", letterSpacing: 1, lineHeight: 1, fontWeight: 700 }}
                                title={`Apagar ${proj.name}`}>···</button>
                            )}
                          </div>
                        ))}

                        {isAdmin && (
                          (showNewProject && activeWorkspace === ws.id) ? (
                            <div style={{ display: "flex", gap: 4, marginTop: 6, padding: "0 4px" }}>
                              <input autoFocus value={newProjectName} onChange={(e) => setNewProjectName(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") addProject(); }} placeholder="Nome do projeto"
                                style={{ flex: 1, background: "var(--sidebar-input-bg)", border: `1px solid var(--sidebar-border)`, borderRadius: 6, padding: "5px 9px", color: "var(--sidebar-text)", fontSize: 12, outline: "none", fontFamily: "inherit" }} />
                              <button onClick={() => addProject()} style={{ background: "var(--sidebar-active-bg)", border: "none", color: "var(--sidebar-text)", borderRadius: 6, padding: "5px 9px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>✓</button>
                              <button onClick={() => setShowNewProject(false)} style={{ background: "var(--sidebar-input-bg)", border: "none", color: "var(--sidebar-text-secondary)", borderRadius: 6, padding: "5px 7px", cursor: "pointer", fontSize: 12 }}>✕</button>
                            </div>
                          ) : (
                            <button onClick={() => { setActiveWorkspace(ws.id); setShowNewProject(true); }} className="sidebar-item"
                              style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", borderRadius: 8, marginTop: 2, fontSize: 12, color: "var(--sidebar-text-muted)", background: "transparent", width: "100%", border: "none", textAlign: "left", cursor: "pointer", fontFamily: "inherit" }}>
                              <span style={{ fontSize: 14 }}>+</span> Novo projeto
                            </button>
                          )
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>

        <div style={{ padding: "12px", borderTop: `1px solid var(--sidebar-border)`, display: "flex", flexDirection: "column", gap: 8 }}>
          <div style={{ padding: "6px 12px", display: "flex", justifyContent: "space-between", fontSize: 12, color: "var(--sidebar-text-muted)" }}>
            <span>Total: <b style={{ color: "var(--sidebar-text)" }}>{filteredTasks.length}</b></span>
            <span style={{ color: "#7CFFB4" }}>✓ {tasks.filter((t) => t.status === "done").length}</span>
            <span style={{ color: "#E2445C" }}>⚠ {tasks.filter((t) => t.deadline && new Date(t.deadline) < new Date() && t.status !== "done").length}</span>
          </div>
        </div>
        </>
        )}
      </aside>

      {/* Main */}
      <div className="app-main" style={{ flex: 1, display: "flex", flexDirection: "column", minWidth: 0, background: "var(--surface)" }}>
        {/* Top bar — dados do usuário no canto superior direito (todas as views) */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, padding: "8px 24px", borderBottom: `1px solid ${theme.border}`, background: "var(--surface)", flexShrink: 0 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            {/* Hambúrguer — abre o drawer no mobile (todas as views) */}
            <button onClick={() => setSidebarOpen(true)} aria-label="Abrir menu" title="Menu"
              className="menu-toggle"
              style={{ alignItems: "center", justifyContent: "center", width: 36, height: 36, borderRadius: 8, border: `1px solid ${theme.border}`, background: theme.inputBg, color: theme.text, cursor: "pointer" }}>
              <MenuIcon size={18} aria-hidden />
            </button>
            {sidebarCollapsed && (
              <button onClick={() => setSidebarCollapsed(false)} aria-label="Expandir menu" title="Expandir menu"
                className="sidebar-expand-btn"
                style={{ background: theme.inputBg, border: `1px solid ${theme.border}`, color: theme.textSecondary, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", width: 36, height: 36, borderRadius: 8 }}>
                <PanelLeftOpen size={18} />
              </button>
            )}
            {pageTitle && (
              <div style={{ marginLeft: 4, lineHeight: 1.1 }}>
                <h1 style={{ fontSize: 19, fontWeight: 800, letterSpacing: -0.4, margin: 0, color: theme.text }}>{pageTitle}</h1>
                {pageSubtitle && <span style={{ fontSize: 11, color: theme.textMuted, fontWeight: 600 }}>{pageSubtitle}</span>}
              </div>
            )}
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          {isAdmin && (
            <button onClick={() => setShowAdmin(true)} title="Painel Admin" aria-label="Painel Admin"
              className="topbar-icon-btn"
              style={{ background: theme.inputBg, border: `1px solid ${theme.border}`, color: "#E2445C", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", width: 36, height: 36, borderRadius: 8 }}>
              <Settings size={16} />
            </button>
          )}
          <NotificationBell theme={theme} onOpenTask={(taskId) => {
            const t = tasks.find((x) => x.id === taskId);
            if (t) setDetailTask(t);
          }} />
          <button
            onClick={() => setProfileOpen(true)}
            title="Editar perfil"
            aria-label="Abrir meu perfil"
            style={{ display: "flex", alignItems: "center", gap: 10, background: "transparent", border: "none", cursor: "pointer", padding: "4px 6px", borderRadius: 10, fontFamily: "inherit" }}
          >
            <div style={{ textAlign: "right", lineHeight: 1.2 }}>
              <div style={{ fontSize: 13, fontWeight: 600, color: theme.text }}>{currentUser.name}</div>
              <div style={{ fontSize: 11, color: theme.textMuted, fontWeight: 600 }}>{ROLES[currentUser.role].label}</div>
            </div>
            <UserAvatar avatar={currentUser.avatar} name={currentUser.name} size={34} background="var(--primary-soft)" />
          </button>
          <button onClick={handleLogout} aria-label="Sair" title="Sair"
            className="topbar-icon-btn"
            style={{ background: theme.inputBg, border: `1px solid ${theme.border}`, color: theme.textSecondary, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", width: 36, height: 36, borderRadius: 8 }}>
            <LogOut size={16} />
          </button>
          </div>
        </div>
        {activeView === "transcricoes" ? (
          <div key="view-transcricoes" style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
            <div style={{ flex: 1, overflowY: "auto", minHeight: 0 }}>
              <TranscriptionsTab theme={theme} />
            </div>
          </div>
        ) : activeView === "tasks" ? (
          <div
            key="view-tasks"
            style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}
          >
        <div className="app-header" style={{ padding: "16px 24px", borderBottom: `1px solid ${theme.border}`, display: "flex", alignItems: "center", gap: 16, flexWrap: "wrap" }}>
          <div style={{ flex: 1, minWidth: 200 }}>
            <h1 style={{ fontSize: 24, fontWeight: 800, letterSpacing: -0.5, margin: 0, display: "flex", alignItems: "center", gap: 10 }}>
              {activeProj ? (
                editingProjName ? (
                  <>
                    <span style={{ width: 12, height: 12, borderRadius: "50%", background: activeProj.color, flexShrink: 0 }} />
                    <input autoFocus value={projNameDraft}
                      onChange={(e) => setProjNameDraft(e.target.value)}
                      onBlur={renameProjectName}
                      onKeyDown={(e) => { if (e.key === "Enter") renameProjectName(); if (e.key === "Escape") setEditingProjName(false); }}
                      style={{ fontSize: 24, fontWeight: 800, letterSpacing: -0.5, color: theme.text, background: theme.inputBg, border: `1px solid ${theme.inputBorder}`, borderRadius: 8, padding: "2px 8px", outline: "none", fontFamily: "inherit", minWidth: 200 }} />
                  </>
                ) : (
                  <>
                    <span style={{ width: 12, height: 12, borderRadius: "50%", background: activeProj.color, flexShrink: 0 }} />
                    {activeProj.name}
                    {isAdmin && (
                      <button onClick={() => { setProjNameDraft(activeProj.name); setEditingProjName(true); }}
                        title="Renomear projeto" aria-label="Renomear projeto"
                        style={{ background: "none", border: "none", color: theme.textMuted, cursor: "pointer", display: "inline-flex", padding: 4, borderRadius: 6 }}>
                        <Pencil size={16} />
                      </button>
                    )}
                  </>
                )
              ) : <><LayoutGrid size={22} aria-hidden /> Todas as Tarefas</>}
            </h1>
            <p style={{ fontSize: 14, color: theme.textMuted, marginTop: 2 }}>{filteredTasks.length} tarefa{filteredTasks.length !== 1 ? "s" : ""}</p>
          </div>
          <div style={{ position: "relative" }}>
            <span aria-hidden style={{ position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)", color: theme.textMuted, display: "flex" }}><Search size={16} /></span>
            <input ref={searchRef} value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar tarefas..."
              aria-label="Buscar tarefas"
              style={{ background: theme.inputBg, border: `1px solid ${theme.border}`, borderRadius: 10, padding: "8px 12px 8px 34px", color: theme.text, fontSize: 14, outline: "none", width: 200, fontFamily: "inherit" }} />
          </div>
          <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}
            style={{ background: theme.inputBg, border: `1px solid ${theme.border}`, borderRadius: 10, padding: "8px 12px", color: theme.text, fontSize: 14, outline: "none", cursor: "pointer", colorScheme: theme.scheme, fontFamily: "inherit" }}>
            <option value="all">Todos Status</option>
            {STATUS_OPTIONS.map((s) => <option key={s.value} value={s.value}>{s.label}</option>)}
          </select>

          {/* Toggle Lista/Kanban */}
          <div role="tablist" aria-label="Modo de visualização" style={{ display: "inline-flex", background: theme.inputBg, border: `1px solid ${theme.border}`, borderRadius: 10, padding: 3 }}>
            <button
              role="tab"
              aria-selected={tasksViewMode === "list"}
              aria-label="Visualização em lista"
              onClick={() => setTasksViewMode("list")}
              title="Lista"
              style={{
                width: 34, height: 30, borderRadius: 7, border: "none",
                background: tasksViewMode === "list" ? "var(--primary)" : "transparent",
                color: tasksViewMode === "list" ? "#fff" : theme.textSecondary,
                cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center",
              }}
            >
              <List size={15} aria-hidden />
            </button>
            <button
              role="tab"
              aria-selected={tasksViewMode === "kanban"}
              aria-label="Visualização Kanban"
              onClick={() => setTasksViewMode("kanban")}
              title="Kanban"
              style={{
                width: 34, height: 30, borderRadius: 7, border: "none",
                background: tasksViewMode === "kanban" ? "var(--primary)" : "transparent",
                color: tasksViewMode === "kanban" ? "#fff" : theme.textSecondary,
                cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center",
              }}
            >
              <KanbanSquare size={15} aria-hidden />
            </button>
          </div>

          {canEdit && (
            <button onClick={addTask}
              style={{ background: "var(--primary)", border: "none", color: "#fff", borderRadius: 10, padding: "9px 20px", cursor: "pointer", fontSize: 14, fontWeight: 700, display: "flex", alignItems: "center", gap: 6, boxShadow: "0 4px 16px var(--primary-ring)" }}>
              <Plus size={16} aria-hidden /> Nova Tarefa
            </button>
          )}
        </div>

        {tasksViewMode === "kanban" ? (
          <KanbanBoard
            tasks={filteredTasks}
            projects={visibleProjects}
            users={users}
            tags={tags}
            canEdit={canEdit}
            defaultProjectId={activeProject !== "all" ? activeProject : (visibleProjects[0]?.id ?? null)}
            onUpdate={updateTask}
            onOpen={(t) => setDetailTask(t)}
            onQuickAdd={(projectId, status) => {
              if (!currentUser) return;
              api.createTask({ title: "Nova tarefa", status, priority: "medium", projectId, assignedTo: currentUser.id })
                .then((nt) => { setTasks((prev) => [nt, ...prev]); setDetailTask(nt); })
                .catch(() => showToast("Erro ao criar tarefa"));
            }}
          />
        ) : (
        <div className="board-list-scroll" style={{ flex: 1, overflowY: "auto", overflowX: "auto", padding: "16px 28px", WebkitOverflowScrolling: "touch" }}>
          {filteredTasks.length === 0 && (
            <EmptyState
              icon={ListChecks}
              title="Nenhuma tarefa encontrada"
              description={canEdit
                ? "Clique em “Nova Tarefa” ou pressione N para começar."
                : "Peça ao admin para compartilhar projetos com você."}
            />
          )}
          <DndContext sensors={dndSensors} collisionDetection={closestCenter} onDragEnd={handleGroupDragEnd}>
            <SortableContext items={groups.map((g) => g.id)} strategy={verticalListSortingStrategy}>
              {groups.map((group) => (
                <SortableGroup key={group.id} id={group.id}>
                  {(dragHandleProps) => (
                    <div className="board-group" style={{ marginBottom: 20, borderRadius: 12, border: `1px solid ${theme.border}`, overflow: "hidden", background: theme.surface }}>
                      <GroupHeader
                        group={group}
                        collapsed={collapsedGroups.has(group.id)}
                        onToggle={() => toggleCollapseGroup(group.id)}
                        taskCount={group.tasks.length}
                        theme={theme}
                        dragHandleProps={dragHandleProps}
                        canEdit={canEdit}
                        onQuickAdd={() => addTaskInGroup(group.projectId, group.kind === "group" && !group.ungrouped ? group.id : null, group.id)}
                        onRename={group.kind === "group" && !group.ungrouped ? (name) => renameTaskGroup(group.id, name) : undefined}
                        onDelete={group.kind === "group" && !group.ungrouped ? () => deleteTaskGroup(group) : undefined}
                      />
                      {!collapsedGroups.has(group.id) && (
                        <>
                          {!isMobile && (
                            <div style={{ display: "grid", gridTemplateColumns: GRID_COLUMNS, padding: "10px 14px", gap: 8, borderBottom: `1px solid ${theme.borderStrong}`, fontSize: 12, fontWeight: 600, color: theme.textMuted, textTransform: "uppercase", letterSpacing: 0.8, background: theme.surfaceHover, borderLeft: `4px solid ${group.color}` }}>
                              <div></div><div>Tarefa</div><div>Status</div><div>{activeProject !== "all" ? "Grupo" : "Projeto"}</div><div>Prazo</div><div>Prioridade</div><div>Pessoa</div><div>Tags</div><div>Link</div><div></div>
                            </div>
                          )}
                          {/* Quick add no TOPO do grupo (estilo monday): clica e digita — desktop */}
                          {canEdit && !isMobile && <div style={{ borderLeft: `4px solid ${group.color}` }}><InlineAddRow groupProjectId={group.projectId} groupId={group.kind === "group" && !group.ungrouped ? group.id : null} theme={theme} onAdd={addTaskInline} /></div>}
                          {group.tasks.map((task) => (
                            isMobile ? (
                              <MobileTaskCard key={task.id} task={task} projects={visibleProjects} users={users} onUpdate={updateTask} onOpen={setDetailTask} theme={theme} canEdit={canEdit} />
                            ) : (
                            <div key={task.id} style={{ borderLeft: `4px solid ${group.color}` }}>
                              <TaskRow task={task} projects={visibleProjects} users={users} tags={tags} onUpdate={updateTask} onOpen={setDetailTask} theme={theme} canEdit={canEdit} isExpanded={expandedTasks.has(task.id)} onToggleExpand={toggleExpandTask} onDelete={deleteTask} groupOptions={activeProject !== "all" && activeProjectGroups.length > 0 ? activeProjectGroups : undefined} />
                              {expandedTasks.has(task.id) && (task.subtasks || []).map((st) => {
                                const stAsTask: Task = { ...task, id: st.id, title: st.title, status: st.status, checked: st.checked, subtasks: [], checklist: [] };
                                return (
                                  <TaskRow key={st.id} task={stAsTask} projects={visibleProjects} users={users} tags={tags} isSubtask canEdit={canEdit}
                                    onUpdate={(updated) => {
                                      const n: Subtask[] = task.subtasks.map((s) =>
                                        s.id === updated.id ? { id: s.id, title: updated.title, status: updated.status, checked: updated.checked } : s
                                      );
                                      updateTask({ ...task, subtasks: n });
                                    }}
                                    onOpen={() => setDetailTask(task)} theme={theme} />
                                );
                              })}
                            </div>
                            )
                          ))}
                        </>
                      )}
                    </div>
                  )}
                </SortableGroup>
              ))}
            </SortableContext>
          </DndContext>

          {canEdit && (
            showNewGroup ? (
              <div style={{ display: "flex", gap: 8, alignItems: "center", padding: "12px 14px", borderRadius: 12, border: `1px dashed ${theme.borderStrong}`, background: theme.surface, marginBottom: 24 }}>
                <input autoFocus value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") addTaskGroup(newGroupName);
                    if (e.key === "Escape") { setNewGroupName(""); setShowNewGroup(false); }
                  }}
                  placeholder="Nome do grupo — ex: Criação"
                  style={{ flex: 1, background: theme.inputBg, border: `1px solid ${theme.border}`, borderRadius: 8, padding: "9px 12px", color: theme.text, fontSize: 14, outline: "none", fontFamily: "inherit" }} />
                <button onClick={() => addTaskGroup(newGroupName)} disabled={!newGroupName.trim()}
                  style={{ background: "var(--primary)", border: "none", color: "#fff", borderRadius: 8, padding: "9px 18px", cursor: newGroupName.trim() ? "pointer" : "default", opacity: newGroupName.trim() ? 1 : 0.5, fontSize: 13, fontWeight: 700, fontFamily: "inherit" }}>Criar grupo</button>
                <button onClick={() => { setNewGroupName(""); setShowNewGroup(false); }}
                  style={{ background: theme.inputBg, border: `1px solid ${theme.border}`, color: theme.textSecondary, borderRadius: 8, padding: "9px 14px", cursor: "pointer", fontSize: 13, fontFamily: "inherit" }}>Cancelar</button>
              </div>
            ) : (
              <button onClick={() => setShowNewGroup(true)}
                style={{ display: "flex", alignItems: "center", gap: 8, width: "100%", padding: "12px 14px", marginBottom: 24, borderRadius: 12, border: `1px dashed ${theme.borderStrong}`, background: "transparent", color: theme.textSecondary, cursor: "pointer", fontSize: 14, fontWeight: 600, fontFamily: "inherit", transition: "all 0.15s" }}
                onMouseEnter={(e) => { e.currentTarget.style.background = theme.surfaceHover; e.currentTarget.style.color = theme.text; }}
                onMouseLeave={(e) => { e.currentTarget.style.background = "transparent"; e.currentTarget.style.color = theme.textSecondary; }}>
                <Plus size={16} aria-hidden /> Novo grupo
              </button>
            )
          )}
        </div>
        )}
          </div>
        ) : activeView === "content" ? (
          <div
            key="view-content"
            style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}
          >
            <ContentBoard
              embedded
              currentUser={currentUser}
              users={users}
              projects={visibleProjects}
            />
          </div>
        ) : activeView === "assets" ? (
          <div key="view-assets" style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
            <AssetsView theme={theme} />
          </div>
        ) : activeView === "notes" ? (
          <div key="view-notes" style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
            <div style={{ flex: 1, overflowY: "auto", minHeight: 0 }}>
              <NotesTab theme={theme} currentUser={currentUser} />
            </div>
          </div>
        ) : activeView === "routine" ? (
          <div key="view-routine" style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
            <div style={{ flex: 1, overflowY: "auto", minHeight: 0 }}>
              <RoutineTab theme={theme} currentUser={currentUser} />
            </div>
          </div>
        ) : activeView === "my-tasks" ? (
          <div key="view-my-tasks" style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
            <div style={{ flex: 1, overflowY: "auto", minHeight: 0 }}>
              <MyTasksTab theme={theme} currentUser={currentUser} tasks={tasks} projects={projects} users={users} tags={tags} canEdit={canEdit} onOpenTask={(t) => setDetailTask(t)} onUpdateTask={updateTask} onReload={loadData} />
            </div>
          </div>
        ) : (
          <div
            key="view-personal"
            style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}
          >
            <div style={{ flex: 1, overflowY: "auto", minHeight: 0 }}>
              <DashboardView
                currentUser={currentUser}
                projects={visibleProjects}
                users={users}
                canEdit={canEdit}
                isAdmin={isAdmin}
                defaultProjectId={visibleProjects[0]?.id ?? null}
                onOpenTask={(t) => setDetailTask(t)}
                onOpenProject={(projId) => { setActiveView("tasks"); setActiveProject(projId); }}
                onSeeAllProjects={() => { setActiveView("tasks"); setActiveProject("all"); }}
                onNewProject={isAdmin ? () => { setActiveView("tasks"); setShowNewProject(true); } : undefined}
              />
            </div>
          </div>
        )}
      </div>

      {detailTask && (
        <TaskDetail task={detailTask} projects={visibleProjects} users={users} tags={tags}
          onUpdate={(u: Task) => { updateTask(u); setDetailTask(u); }}
          onClose={() => setDetailTask(null)} theme={theme} canEdit={canEdit} />
      )}

      {showAdmin && isAdmin && (
        <AdminPanel users={users} projects={projects} tasks={tasks} tags={tags}
          workspaces={workspaces}
          onUpdateUsers={setUsers} onUpdateProjects={setProjects} onUpdateTags={setTags}
          onUpdateWorkspaces={setWorkspaces}
          onClose={() => setShowAdmin(false)} theme={theme} currentUser={currentUser} />
      )}

      {/* Toast notifications */}
      <div role="status" aria-live="polite" style={{ position: "fixed", bottom: 20, right: 20, zIndex: 9999, display: "flex", flexDirection: "column", gap: 8 }}>
        {toasts.map((t) => (
          <div key={t.id} style={{
            padding: "12px 20px", borderRadius: 10, fontSize: 13, fontWeight: 600,
            background: t.type === "error" ? "rgba(226,68,92,0.95)" : "rgba(0,200,117,0.95)",
            color: "#fff", boxShadow: "0 4px 20px rgba(0,0,0,0.3)",
            animation: "fadeUp 0.25s ease-out",
          }}>
            <span aria-hidden style={{ marginRight: 6 }}>{t.type === "error" ? "⚠" : "✓"}</span>
            {t.message}
          </div>
        ))}
      </div>

      <ConfirmDialog
        open={!!confirm}
        title={confirm?.title ?? ""}
        description={confirm?.description}
        confirmLabel="Apagar"
        destructive
        onConfirm={() => confirm?.onConfirm()}
        onCancel={() => setConfirm(null)}
      />

      <ShortcutsHelp open={shortcutsOpen} shortcuts={shortcuts} onClose={() => setShortcutsOpen(false)} />

      <ProfilePanel
        open={profileOpen}
        user={currentUser}
        onClose={() => setProfileOpen(false)}
        onUserUpdated={(u) => {
          setCurrentUser(u);
          // Mantém a lista de users em sync também
          setUsers((prev) => prev.map((x) => (x.id === u.id ? { ...x, name: u.name, avatar: u.avatar } : x)));
        }}
      />

      {/* Captura por voz (FAB flutuante) */}
      <VoiceCapture
        projects={visibleProjects}
        currentUser={currentUser}
        onCreated={() => { api.getTasks().then(setTasks).catch(() => {}); }}
        onToast={showToast}
      />
    </div>
  );
}

"use client";

import { useMemo } from "react";
import { createAvatar, type Style } from "@dicebear/core";
import { adventurer, notionists, personas, avataaars } from "@dicebear/collection";

/** 8 seeds compartilhados entre os 4 estilos */
export const AVATAR_SEEDS = [
  "Ada", "Buzz", "Coco", "Drift", "Echo", "Fox", "Gigi", "Holly",
] as const;
export type AvatarSeed = (typeof AVATAR_SEEDS)[number];

/** Estilos suportados — chave usada como prefixo no campo `avatar` */
export const AVATAR_STYLES = [
  { id: "adventurer", label: "Aventureiro",  hint: "fofo, chibi",        style: adventurer  as unknown as Style<object> },
  { id: "notionists", label: "Notion",       hint: "linha minimalista",  style: notionists  as unknown as Style<object> },
  { id: "personas",   label: "Persona",      hint: "ilustração formal",  style: personas    as unknown as Style<object> },
  { id: "avataaars",  label: "Clássico",     hint: "estilo executivo",   style: avataaars   as unknown as Style<object> },
] as const;

export type AvatarStyleId = (typeof AVATAR_STYLES)[number]["id"];
const STYLE_BY_ID = new Map<AvatarStyleId, Style<object>>(
  AVATAR_STYLES.map((s) => [s.id, s.style as Style<object>])
);

const BACKGROUND_COLORS = ["b6e3f4", "c0aede", "d1d4f9", "ffd5dc", "ffdfbf"];

function looksLikeEmoji(s: string): boolean {
  if (!s) return true;
  if (s.length > 4) return false;
  return /\p{Extended_Pictographic}/u.test(s);
}

/** Faz parse do campo `avatar`. Aceita "style:seed", "seed" (legacy = adventurer) ou emoji. */
export function parseAvatar(raw: string | null | undefined): {
  kind: "emoji" | "dicebear";
  emoji?: string;
  styleId?: AvatarStyleId;
  seed?: string;
} {
  if (!raw) return { kind: "emoji", emoji: "👤" };
  if (looksLikeEmoji(raw)) return { kind: "emoji", emoji: raw };
  if (raw.includes(":")) {
    const [styleId, seed] = raw.split(":", 2);
    if (STYLE_BY_ID.has(styleId as AvatarStyleId) && seed) {
      return { kind: "dicebear", styleId: styleId as AvatarStyleId, seed };
    }
  }
  // Legacy seed sem prefixo → adventurer
  return { kind: "dicebear", styleId: "adventurer", seed: raw };
}

/** Monta o id "style:seed" a partir das partes — usado pelo picker. */
export function composeAvatar(styleId: AvatarStyleId, seed: string): string {
  return `${styleId}:${seed}`;
}

interface UserAvatarProps {
  avatar?: string | null;
  name: string;
  size?: number;
  background?: string;
  className?: string;
}

export function UserAvatar({ avatar, name, size = 32, background, className }: UserAvatarProps) {
  const parsed = useMemo(() => parseAvatar(avatar), [avatar]);

  const dataUri = useMemo(() => {
    if (parsed.kind !== "dicebear" || !parsed.styleId || !parsed.seed) return null;
    const style = STYLE_BY_ID.get(parsed.styleId);
    if (!style) return null;
    return createAvatar(style, {
      seed: parsed.seed,
      backgroundColor: BACKGROUND_COLORS,
      radius: 50,
    }).toDataUri();
  }, [parsed]);

  if (parsed.kind === "emoji") {
    return (
      <span
        aria-label={name}
        title={name}
        className={className}
        style={{
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
          width: size,
          height: size,
          borderRadius: "50%",
          background: background ?? "var(--primary-soft)",
          fontSize: Math.round(size * 0.55),
          flexShrink: 0,
          userSelect: "none",
        }}
      >
        {parsed.emoji}
      </span>
    );
  }

  return (
    <img
      src={dataUri ?? ""}
      alt={name}
      title={name}
      width={size}
      height={size}
      className={className}
      style={{
        width: size,
        height: size,
        borderRadius: "50%",
        flexShrink: 0,
        display: "block",
        background: background ?? "var(--primary-soft)",
      }}
    />
  );
}

